func (p *Printer) emitSnippetNode(node store.Node, snippetElement *SnippetElement) {
	switch snippetElement.Kind {
	case SnippetKindTabStop:
		p.emitTabStop(node, snippetElement)
	default:
		panic(fmt.Sprintf("Unhandled snippet element kind: %v", snippetElement.Kind))
	}
}

func (p *Printer) emitTabStop(node store.Node, snippetElement *SnippetElement) {
	debug.Assert(node.Kind() == ast.KindEmptyStatement, "Snippet tab stops can only be emitted on empty statements")
	p.writer.RawWrite(fmt.Sprintf("$%d", snippetElement.Order))
}

func (p *Printer) emitIdentifierText(node store.Identifier) {
	f := store.Node(node).File()
	debug.Assert(f == nil || p.currentSourceFile == nil || f.FileName() == p.currentSourceFile.FileName())
	text := p.getTextOfNode(store.Node(node), false /*includeTrivia*/)

	if p.IdToSymbol != nil {
		if symbol, ok := p.IdToSymbol[store.Node(node).Key()]; ok {
			p.writeSymbol(text, symbol)
			return
		}
	}
	p.write(text)
}

func (p *Printer) emitIdentifierName(node store.Identifier) {
	state := p.enterNode(store.Node(node))
	p.emitIdentifierText(node)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitIdentifierNameNode(node store.Node) {
	if node.IsNil() {
		return
	}
	p.emitIdentifierName(node.AsIdentifier())
}

func (p *Printer) getUniqueHelperName(name string) store.Node {
	helperName := p.uniqueHelperNames[name]
	if helperName.IsNil() {
		helperName := p.emitContext.Factory.NewUniqueNameEx(name, AutoGenerateOptions{Flags: GeneratedIdentifierFlagsFileLevel | GeneratedIdentifierFlagsOptimistic})
		p.generateName(helperName)
		p.uniqueHelperNames[name] = helperName
		return helperName
	}
	return p.emitContext.Factory.Factory.Clone(helperName)
}

func (p *Printer) emitIdentifierReference(node store.Identifier) {
	if (!p.externalHelpersModuleName.IsNil() || p.uniqueHelperNames != nil) &&
		p.emitContext.EmitFlags(store.Node(node))&EFHelperName != 0 {
		if !p.externalHelpersModuleName.IsNil() {
			// Substitute `__helper` with `tslib_1.__helper`
			helper := p.emitContext.Factory.NewPropertyAccessExpression(
				p.emitContext.Factory.Factory.Clone(p.externalHelpersModuleName),
				store.Node{}, /*questionDotToken*/
				p.emitContext.Factory.Factory.Clone(store.Node(node)),
				ast.NodeFlagsNone,
			)
			p.emitContext.AssignCommentAndSourceMapRanges(helper, store.Node(node))
			p.emitPropertyAccessExpression(helper.AsPropertyAccessExpression())
			return
		}
		if p.uniqueHelperNames != nil {
			// Substitute `__helper` with `__helper_1` if there is a conflict in an ES module.
			helperName := p.getUniqueHelperName(node.Text())
			p.emitContext.AssignCommentAndSourceMapRanges(helperName, store.Node(node))
			node = helperName.AsIdentifier()
		}
	}

	state := p.enterNode(store.Node(node))
	p.emitIdentifierText(node)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitBindingIdentifier(node store.Identifier) {
	if p.uniqueHelperNames != nil &&
		p.emitContext.EmitFlags(store.Node(node))&EFHelperName != 0 {
		// Substitute `__helper` with `__helper_1` if there is a conflict in an ES module.
		helperName := p.getUniqueHelperName(node.Text())
		p.emitContext.AssignCommentAndSourceMapRanges(helperName, store.Node(node))
		node = helperName.AsIdentifier()
	}

	state := p.enterNode(store.Node(node))
	p.emitIdentifierText(node)
	p.exitNode(store.Node(node), state)
}

