func (p *Printer) emitClassElement(node store.Node) {
	switch node.Kind() {
	case ast.KindPropertyDeclaration:
		p.emitPropertyDeclaration(node.AsPropertyDeclaration())
	case ast.KindMethodDeclaration:
		p.emitMethodDeclaration(node.AsMethodDeclaration())
	case ast.KindClassStaticBlockDeclaration:
		p.emitClassStaticBlockDeclaration(node.AsClassStaticBlockDeclaration())
	case ast.KindConstructor:
		p.emitConstructor(node.AsConstructorDeclaration())
	case ast.KindGetAccessor:
		p.emitGetAccessorDeclaration(node.AsGetAccessorDeclaration())
	case ast.KindSetAccessor:
		p.emitSetAccessorDeclaration(node.AsSetAccessorDeclaration())
	case ast.KindIndexSignature:
		p.emitIndexSignature(node.AsIndexSignatureDeclaration())
	case ast.KindSemicolonClassElement:
		p.emitSemicolonClassElement(node)
	case ast.KindNotEmittedStatement:
		p.emitNotEmittedStatement(node)
	case ast.KindJSTypeAliasDeclaration:
		p.emitTypeAliasDeclaration(node.AsTypeAliasDeclaration())
	default:
		panic(fmt.Sprintf("unexpected ClassElement: %v", node.Kind()))
	}
}

func (p *Printer) emitTypeElement(node store.Node) {
	switch node.Kind() {
	case ast.KindPropertySignature:
		p.emitPropertySignature(node.AsPropertySignatureDeclaration())
	case ast.KindMethodSignature:
		p.emitMethodSignature(node.AsMethodSignatureDeclaration())
	case ast.KindCallSignature:
		p.emitCallSignature(node.AsCallSignatureDeclaration())
	case ast.KindConstructSignature:
		p.emitConstructSignature(node.AsConstructSignatureDeclaration())
	case ast.KindGetAccessor:
		p.emitGetAccessorDeclaration(node.AsGetAccessorDeclaration())
	case ast.KindSetAccessor:
		p.emitSetAccessorDeclaration(node.AsSetAccessorDeclaration())
	case ast.KindIndexSignature:
		p.emitIndexSignature(node.AsIndexSignatureDeclaration())
	case ast.KindNotEmittedTypeElement:
		p.emitNotEmittedTypeElement(node)
	default:
		panic(fmt.Sprintf("unexpected TypeElement: %v", node.Kind()))
	}
}

func (p *Printer) emitObjectLiteralElement(node store.Node) {
	switch node.Kind() {
	case ast.KindPropertyAssignment:
		p.emitPropertyAssignment(node.AsPropertyAssignment())
	case ast.KindShorthandPropertyAssignment:
		p.emitShorthandPropertyAssignment(node.AsShorthandPropertyAssignment())
	case ast.KindSpreadAssignment:
		p.emitSpreadAssignment(node.AsSpreadAssignment())
	case ast.KindMethodDeclaration:
		p.emitMethodDeclaration(node.AsMethodDeclaration())
	case ast.KindGetAccessor:
		p.emitGetAccessorDeclaration(node.AsGetAccessorDeclaration())
	case ast.KindSetAccessor:
		p.emitSetAccessorDeclaration(node.AsSetAccessorDeclaration())
	default:
		panic(fmt.Sprintf("unhandled ObjectLiteralElement: %v", node.Kind()))
	}
}

func (p *Printer) emitKeywordTypeNode(node store.Node) {
	p.emitKeywordNode(node)
}

func (p *Printer) emitTypePredicateParameterName(node store.Node) {
	switch node.Kind() {
	case ast.KindIdentifier:
		p.emitIdentifierReference(node.AsIdentifier())
	case ast.KindThisType:
		p.emitThisType(node)
	default:
		panic(fmt.Sprintf("unexpected TypePredicateParameterName: %v", node.Kind()))
	}
}

func (p *Printer) emitTypePredicate(node store.TypePredicateNode) {
	state := p.enterNode(store.Node(node))
	if !node.AssertsModifier().IsNil() {
		p.emitTokenNode(node.AssertsModifier())
		p.writeSpace()
	}
	p.emitTypePredicateParameterName(node.ParameterName())
	if !node.Type().IsNil() {
		p.writeSpace()
		p.writeKeyword("is")
		p.writeSpace()
		p.emitTypeNodeOutsideExtends(node.Type())
	}
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitTypeArgument(node store.Node) {
	p.emitTypeNodeOutsideExtends(node)
}

func (p *Printer) emitTypeArguments(parentNode store.Node, nodes store.List) {
	if nodes.IsNil() {
		return
	}
	p.emitList((*Printer).emitTypeParameterDeclarationNode, parentNode, nodes, LFTypeArguments /*|core.IfElse(p.shouldAllowTrailingComma(parentNode, nodes), LFAllowTrailingComma, LFNone)*/) // TODO: preserve trailing comma after Strada migration
}

func (p *Printer) emitTypeReference(node store.TypeReferenceNode) {
	state := p.enterNode(store.Node(node))
	p.emitEntityName(node.TypeName())
	p.emitTypeArguments(store.Node(node), node.TypeArguments())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitReturnType(node store.Node) {
	if node.IsNil() {
		return
	}
	p.writePunctuation("=>")
	p.writeSpace()
	if p.inExtends && node.Kind() == ast.KindInferType && !node.AsInferTypeNode().TypeParameter().AsTypeParameterDeclaration().Constraint().IsNil() {
		// if the parent FunctionTypeNode or ConstructorTypeNode is in the `extends` clause of a ConditionalTypeNode,
		// we must parenthesize `infer ... extends ...` so as not to result in an ambiguous parse.
		//
		// `T extends () => infer U extends V ? W : X` would parse the `? W : X` as part of a ConditionalTypeNode in the
		// return type of the FunctionTypeNode, thus we must emit as `T extends () => (infer U extends V) ? W : X`
		p.emitTypeNodePreservingExtends(node, ast.TypePrecedenceHighest)
	} else {
		p.emitTypeNodePreservingExtends(node, ast.TypePrecedenceLowest)
	}
}

func (p *Printer) emitFunctionType(node store.FunctionTypeNode) {
	state := p.enterNode(store.Node(node))
	indented := p.shouldEmitIndented(store.Node(node))
	p.increaseIndentIf(indented)
	p.pushNameGenerationScope(store.Node(node))
	// !!! in the old emitter, quickinfo uses type arguments in place of type parameters for instantiated signatures
	p.emitTypeParameters(store.Node(node), node.TypeParameters())
	p.emitParameters(store.Node(node), node.Parameters())
	p.writeSpace()
	p.emitReturnType(node.Type())
	p.popNameGenerationScope(store.Node(node))
	p.decreaseIndentIf(indented)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitConstructorType(node store.ConstructorTypeNode) {
	state := p.enterNode(store.Node(node))
	p.emitModifierList(store.Node(node), node.Modifiers(), false /*allowDecorators*/)
	p.writeKeyword("new")
	p.writeSpace()
	indented := p.shouldEmitIndented(store.Node(node))
	p.increaseIndentIf(indented)
	p.pushNameGenerationScope(store.Node(node))
	// !!! in the old emitter, quickinfo uses type arguments in place of type parameters for instantiated signatures
	p.emitTypeParameters(store.Node(node), node.TypeParameters())
	p.emitParameters(store.Node(node), node.Parameters())
	p.writeSpace()
	p.emitReturnType(node.Type())
	p.popNameGenerationScope(store.Node(node))
	p.decreaseIndentIf(indented)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitTypeQuery(node store.TypeQueryNode) {
	state := p.enterNode(store.Node(node))
	p.writeKeyword("typeof")
	p.writeSpace()
	p.emitEntityName(node.ExprName())
	p.emitTypeArguments(store.Node(node), node.TypeArguments())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitTypeLiteral(node store.TypeLiteralNode) {
	state := p.enterNode(store.Node(node))
	p.pushNameGenerationScope(store.Node(node))
	p.generateAllMemberNames(node.Members())
	p.writePunctuation("{")
	flags := core.IfElse(p.shouldEmitOnSingleLine(store.Node(node)), LFSingleLineTypeLiteralMembers, LFMultiLineTypeLiteralMembers)
	p.emitList((*Printer).emitTypeElement, store.Node(node), node.Members(), flags|LFNoSpaceIfEmpty)
	p.writePunctuation("}")
	p.popNameGenerationScope(store.Node(node))
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitArrayType(node store.ArrayTypeNode) {
	state := p.enterNode(store.Node(node))
	p.emitPostfixTypeOperand(node.ElementType(), store.Node(node))
	p.writePunctuation("[")
	p.writePunctuation("]")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitPostfixTypeOperand(operand store.Node, parent store.Node) {
	if store.IsParseTreeNode(parent) && operand.Kind() == ast.KindTypeQuery {
		p.emitTypeNode(operand, ast.TypePrecedenceTypeOperator)
		return
	}
	p.emitTypeNode(operand, ast.TypePrecedencePostfix)
}

func (p *Printer) emitTupleElementType(node store.Node) {
	p.emitTypeNodeOutsideExtends(node)
}

func (p *Printer) emitTupleType(node store.TupleTypeNode) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindOpenBracketToken, int(store.Node(node).Pos()), WriteKindPunctuation, store.Node(node))
	flags := core.IfElse(p.shouldEmitOnSingleLine(store.Node(node)), LFSingleLineTupleTypeElements, LFMultiLineTupleTypeElements)
	p.emitList((*Printer).emitTupleElementType, store.Node(node), node.Elements(), flags|LFNoSpaceIfEmpty)
	p.emitToken(ast.KindCloseBracketToken, int(node.Elements().End()), WriteKindPunctuation, store.Node(node))
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitRestType(node store.RestTypeNode) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("...")
	p.emitTypeNodeOutsideExtends(node.Type())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitOptionalType(node store.OptionalTypeNode) {
	state := p.enterNode(store.Node(node))
	// !!! May need extra parenthesization if we also have JSDocNullableType
	p.emitPostfixTypeOperand(node.Type(), store.Node(node))
	p.writePunctuation("?")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitNamedTupleMember(node store.NamedTupleMember) {
	state := p.enterNode(store.Node(node))
	p.emitPunctuationNode(node.DotDotDotToken())
	p.emitIdentifierName(node.Name().AsIdentifier())
	p.emitPunctuationNode(node.QuestionToken())
	p.emitToken(ast.KindColonToken, greatestEnd(int(node.Name().End()), node.QuestionToken()), WriteKindPunctuation, store.Node(node))
	p.writeSpace()
	p.emitTypeNodeOutsideExtends(node.Type())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitUnionTypeConstituent(node store.Node) {
	p.emitTypeNode(node, ast.TypePrecedenceTypeOperator)
}

func (p *Printer) emitUnionType(node store.UnionTypeNode) {
	state := p.enterNode(store.Node(node))
	p.emitList((*Printer).emitUnionTypeConstituent, store.Node(node), node.Types(), LFUnionTypeConstituents)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitIntersectionTypeConstituent(node store.Node) {
	p.emitTypeNode(node, ast.TypePrecedenceTypeOperator)
}

func (p *Printer) emitIntersectionType(node store.IntersectionTypeNode) {
	state := p.enterNode(store.Node(node))
	p.emitList((*Printer).emitIntersectionTypeConstituent, store.Node(node), node.Types(), LFIntersectionTypeConstituents /*, parenthesizer.parenthesizeConstituentTypeOfIntersectionType*/) // !!!
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitConditionalType(node store.ConditionalTypeNode) {
	state := p.enterNode(store.Node(node))
	p.emitTypeNode(node.CheckType(), ast.TypePrecedenceUnion)
	p.writeSpace()
	p.writeKeyword("extends")
	p.writeSpace()
	p.emitTypeNodeInExtends(node.ExtendsType())
	p.writeSpace()
	p.writePunctuation("?")
	p.writeSpace()
	p.emitTypeNodeOutsideExtends(node.TrueType())
	p.writeSpace()
	p.writePunctuation(":")
	p.writeSpace()
	p.emitTypeNodeOutsideExtends(node.FalseType())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitInferTypeParameter(node store.TypeParameterDeclaration) {
	state := p.enterNode(store.Node(node))
	p.emitBindingIdentifier(node.Name().AsIdentifier())
	if !node.Constraint().IsNil() {
		p.writeSpace()
		p.writeKeyword("extends")
		p.writeSpace()
		p.emitTypeNodeInExtends(node.Constraint())
	}
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitInferType(node store.InferTypeNode) {
	state := p.enterNode(store.Node(node))
	p.writeKeyword("infer")
	p.writeSpace()
	p.emitInferTypeParameter(node.TypeParameter().AsTypeParameterDeclaration())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitParenthesizedType(node store.ParenthesizedTypeNode) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("(")
	p.emitTypeNodeOutsideExtends(node.Type())
	p.writePunctuation(")")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitThisType(node store.Node) {
	state := p.enterNode(node)
	p.writeKeyword("this")
	p.exitNode(node, state)
}

func (p *Printer) emitTypeOperator(node store.TypeOperatorNode) {
	state := p.enterNode(store.Node(node))
	p.emitToken(node.Operator(), int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitTypeNode(node.Type(), core.IfElse(node.Operator() == ast.KindReadonlyKeyword, ast.TypePrecedencePostfix, ast.TypePrecedenceTypeOperator))
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitIndexedAccessType(node store.IndexedAccessTypeNode) {
	state := p.enterNode(store.Node(node))
	p.emitPostfixTypeOperand(node.ObjectType(), store.Node(node))
	p.writePunctuation("[")
	p.emitTypeNodeOutsideExtends(node.IndexType())
	p.writePunctuation("]")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitMappedTypeParameter(node store.TypeParameterDeclaration) {
	state := p.enterNode(store.Node(node))
	p.emitBindingIdentifier(node.Name().AsIdentifier())
	p.writeSpace()
	p.writeKeyword("in")
	p.writeSpace()
	p.emitTypeNodeOutsideExtends(node.Constraint())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitMappedType(node store.MappedTypeNode) {
	state := p.enterNode(store.Node(node))
	singleLine := p.shouldEmitOnSingleLine(store.Node(node))
	p.writePunctuation("{")
	if singleLine {
		p.writeSpace()
	} else {
		p.writeLine()
		p.increaseIndent()
	}
	if !node.ReadonlyToken().IsNil() {
		p.emitTokenNode(node.ReadonlyToken())
		if node.ReadonlyToken().Kind() != ast.KindReadonlyKeyword {
			p.writeKeyword("readonly")
		}
		p.writeSpace()
	}
	p.writePunctuation("[")
	p.emitMappedTypeParameter(node.TypeParameter().AsTypeParameterDeclaration())
	if !node.NameType().IsNil() {
		p.writeSpace()
		p.writeKeyword("as")
		p.writeSpace()
		p.emitTypeNodeOutsideExtends(node.NameType())
	}
	p.writePunctuation("]")
	if !node.QuestionToken().IsNil() {
		p.emitPunctuationNode(node.QuestionToken())
		if node.QuestionToken().Kind() != ast.KindQuestionToken {
			p.writePunctuation("?")
		}
	}
	if !node.Type().IsNil() {
		p.writePunctuation(":")
		p.writeSpace()
		p.emitTypeNodeOutsideExtends(node.Type())
	}
	p.writeTrailingSemicolon()
	if !node.Members().IsNil() {
		if node.Members().Len() > 0 {
			if singleLine {
				p.writeSpace()
			} else {
				p.writeLine()
			}
			p.emitList((*Printer).emitTypeElement, store.Node(node), node.Members(), LFPreserveLines)
		}
	}
	if singleLine {
		p.writeSpace()
	} else {
		p.writeLine()
		p.decreaseIndent()
	}
	p.writePunctuation("}")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitLiteralType(node store.LiteralTypeNode) {
	state := p.enterNode(store.Node(node))
	p.emitExpression(node.Literal(), ast.OperatorPrecedenceComma)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitTemplateTypeSpan(node store.TemplateLiteralTypeSpan) {
	state := p.enterNode(store.Node(node))
	p.emitTypeNodeOutsideExtends(node.Type())
	p.emitTemplateMiddleTail(node.Literal())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitTemplateTypeSpanNode(node store.Node) {
	p.emitTemplateTypeSpan(node.AsTemplateLiteralTypeSpan())
}

func (p *Printer) emitTemplateType(node store.TemplateLiteralTypeNode) {
	state := p.enterNode(store.Node(node))
	p.emitTemplateHead(node.Head().AsTemplateHead())
	p.emitList((*Printer).emitTemplateTypeSpanNode, store.Node(node), node.TemplateSpans(), LFTemplateExpressionSpans)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitImportTypeNodeAttributes(node store.ImportAttributes) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("{")
	p.writeSpace()
	p.writeKeyword(core.IfElse(node.Token() == ast.KindAssertKeyword, "assert", "with"))
	p.writePunctuation(":")
	p.writeSpace()
	p.emitList((*Printer).emitImportAttributeNode, store.Node(node), node.Attributes(), LFImportAttributes)
	p.writeSpace()
	p.writePunctuation("}")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitImportTypeNode(node store.ImportTypeNode) {
	state := p.enterNode(store.Node(node))
	if node.IsTypeOf() {
		p.writeKeyword("typeof")
		p.writeSpace()
	}
	p.writeKeyword("import")
	p.writePunctuation("(")
	p.emitTypeNodeOutsideExtends(node.Argument())
	if !node.Attributes().IsNil() {
		p.writePunctuation(",")
		p.writeSpace()
		p.emitImportTypeNodeAttributes(node.Attributes().AsImportAttributes())
	}
	p.writePunctuation(")")
	if !node.Qualifier().IsNil() {
		p.writePunctuation(".")
		p.emitEntityName(node.Qualifier())
	}
	p.emitTypeArguments(store.Node(node), node.TypeArguments())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitTypeNodeInExtends(node store.Node) {
	savedInExtends := p.inExtends
	p.inExtends = true
	p.emitTypeNodePreservingExtends(node, ast.TypePrecedenceLowest)
	p.inExtends = savedInExtends
}

func (p *Printer) emitTypeNodeOutsideExtends(node store.Node) {
	savedInExtends := p.inExtends
	p.inExtends = false
	p.emitTypeNodePreservingExtends(node, ast.TypePrecedenceLowest)
	p.inExtends = savedInExtends
}

func (p *Printer) emitTypeNodePreservingExtends(node store.Node, precedence ast.TypePrecedence) {
	p.emitTypeNode(node, precedence)
}

func (p *Printer) emitTypeNode(node store.Node, precedence ast.TypePrecedence) {
	if p.inExtends && precedence <= ast.TypePrecedenceConditional {
		// in the `extends` clause of a ConditionalType or InferType, a ConditionalType must be parenthesized
		precedence = ast.TypePrecedenceFunction
	}

	savedInExtends := p.inExtends
	parens := store.GetTypeNodePrecedence(node) < precedence
	if parens {
		p.inExtends = false
		p.writePunctuation("(")
	}

	switch node.Kind() {
	// Keyword Types
	case ast.KindAnyKeyword,
		ast.KindUnknownKeyword,
		ast.KindNumberKeyword,
		ast.KindBigIntKeyword,
		ast.KindObjectKeyword,
		ast.KindBooleanKeyword,
		ast.KindStringKeyword,
		ast.KindSymbolKeyword,
		ast.KindVoidKeyword,
		ast.KindUndefinedKeyword,
		ast.KindNeverKeyword,
		ast.KindIntrinsicKeyword:
		p.emitKeywordTypeNode(node)

	// Types
	case ast.KindTypePredicate:
		p.emitTypePredicate(node.AsTypePredicateNode())
	case ast.KindTypeReference:
		p.emitTypeReference(node.AsTypeReferenceNode())
	case ast.KindFunctionType:
		p.emitFunctionType(node.AsFunctionTypeNode())
	case ast.KindConstructorType:
		p.emitConstructorType(node.AsConstructorTypeNode())
	case ast.KindTypeQuery:
		p.emitTypeQuery(node.AsTypeQueryNode())
	case ast.KindTypeLiteral:
		p.emitTypeLiteral(node.AsTypeLiteralNode())
	case ast.KindArrayType:
		p.emitArrayType(node.AsArrayTypeNode())
	case ast.KindTupleType:
		p.emitTupleType(node.AsTupleTypeNode())
	case ast.KindOptionalType:
		p.emitOptionalType(node.AsOptionalTypeNode())
	case ast.KindRestType:
		p.emitRestType(node.AsRestTypeNode())
	case ast.KindUnionType:
		p.emitUnionType(node.AsUnionTypeNode())
	case ast.KindIntersectionType:
		p.emitIntersectionType(node.AsIntersectionTypeNode())
	case ast.KindConditionalType:
		p.emitConditionalType(node.AsConditionalTypeNode())
	case ast.KindInferType:
		p.emitInferType(node.AsInferTypeNode())
	case ast.KindParenthesizedType:
		p.emitParenthesizedType(node.AsParenthesizedTypeNode())
	case ast.KindThisType:
		p.emitThisType(node)
	case ast.KindTypeOperator:
		p.emitTypeOperator(node.AsTypeOperatorNode())
	case ast.KindIndexedAccessType:
		p.emitIndexedAccessType(node.AsIndexedAccessTypeNode())
	case ast.KindMappedType:
		p.emitMappedType(node.AsMappedTypeNode())
	case ast.KindLiteralType:
		p.emitLiteralType(node.AsLiteralTypeNode())
	case ast.KindNamedTupleMember:
		p.emitNamedTupleMember(node.AsNamedTupleMember())
	case ast.KindTemplateLiteralType:
		p.emitTemplateType(node.AsTemplateLiteralTypeNode())
	case ast.KindTemplateLiteralTypeSpan:
		p.emitTemplateTypeSpan(node.AsTemplateLiteralTypeSpan())
	case ast.KindImportType:
		p.emitImportTypeNode(node.AsImportTypeNode())

	case ast.KindPropertyAccessExpression:
		// Occurs in pseudo-types such as `f<T>.C`, where `f` is a generic function and `C` is a local type
		p.emitPropertyAccessExpression(node.AsPropertyAccessExpression())
	case ast.KindExpressionWithTypeArguments:
		// !!! Should this actually be considered a type?
		p.emitExpressionWithTypeArguments(node.AsExpressionWithTypeArguments())

	case ast.KindJSDocAllType:
		p.emitJSDocAllType(node)
	case ast.KindJSDocNonNullableType:
		p.emitJSDocNonNullableType(node.AsJSDocNonNullableType())
	case ast.KindJSDocNullableType:
		p.emitJSDocNullableType(node.AsJSDocNullableType())
	case ast.KindJSDocOptionalType:
		p.emitJSDocOptionalType(node.AsJSDocOptionalType())
	case ast.KindJSDocVariadicType:
		p.emitJSDocVariadicType(node.AsJSDocVariadicType())

	default:
		panic(fmt.Sprintf("unhandled TypeNode: %v", node.Kind()))
	}

	if parens {
		p.writePunctuation(")")
	}

	p.inExtends = savedInExtends
}

func (p *Printer) emitObjectBindingPattern(node store.BindingPattern) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("{")
	p.emitList((*Printer).emitBindingElementNode, store.Node(node), node.Elements(), LFObjectBindingPatternElements)
	p.writePunctuation("}")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitArrayBindingPattern(node store.BindingPattern) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("[")
	p.emitList((*Printer).emitBindingElementNode, store.Node(node), node.Elements(), LFArrayBindingPatternElements)
	p.writePunctuation("]")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitBindingElement(node store.BindingElement) {
	state := p.enterNode(store.Node(node))
	p.emitTokenNode(node.DotDotDotToken())
	if !node.PropertyName().IsNil() {
		p.emitPropertyName(node.PropertyName())
		p.writePunctuation(":")
		p.writeSpace()
	}
	// Old parser used `OmittedExpression` as a substitute for `Elision`. New parser uses a `BindingElement` with nil members
	if name := node.Name(); !name.IsNil() {
		p.emitBindingName(name)
		p.emitInitializer(node.Initializer(), int(node.Name().End()), store.Node(node))
	}
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitBindingElementNode(node store.Node) {
	p.emitBindingElement(node.AsBindingElement())
}

func (p *Printer) emitJSDocAllType(node store.Node) {
	p.emitKeywordNode(node)
}

func (p *Printer) emitJSDocNonNullableType(node store.JSDocNonNullableType) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("!")
	p.emitTypeNode(node.Type(), ast.TypePrecedenceNonArray)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJSDocNullableType(node store.JSDocNullableType) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("?")
	p.emitTypeNode(node.Type(), ast.TypePrecedenceNonArray)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJSDocOptionalType(node store.JSDocOptionalType) {
	state := p.enterNode(store.Node(node))
	p.emitTypeNode(node.Type(), ast.TypePrecedenceJSDoc)
	p.writePunctuation("=")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJSDocVariadicType(node store.JSDocVariadicType) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("...")
	p.emitTypeNode(node.Type(), ast.TypePrecedenceJSDoc)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitKeywordExpression(node store.Node) {
	p.emitKeywordNode(node)
}

func (p *Printer) emitArrayLiteralExpressionElement(node store.Node) {
	p.emitExpression(node, ast.OperatorPrecedenceSpread)
}

func (p *Printer) emitArrayLiteralExpression(node store.ArrayLiteralExpression) {
	state := p.enterNode(store.Node(node))
	p.emitList((*Printer).emitArrayLiteralExpressionElement, store.Node(node), node.Elements(), LFArrayLiteralExpressionElements|core.IfElse(node.MultiLine(), LFPreferNewLine, LFNone))
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitObjectLiteralExpression(node store.ObjectLiteralExpression) {
	state := p.enterNode(store.Node(node))
	indented := p.shouldEmitIndented(store.Node(node))
	p.increaseIndentIf(indented)
	p.pushNameGenerationScope(store.Node(node))
	p.generateAllMemberNames(node.Properties())
	p.emitList((*Printer).emitObjectLiteralElement, store.Node(node), node.Properties(), LFObjectLiteralExpressionProperties|
		core.IfElse(node.MultiLine(), LFPreferNewLine, LFNone)|
		core.IfElse(p.shouldAllowTrailingComma(store.Node(node), node.Properties()), LFAllowTrailingComma, LFNone))
	p.popNameGenerationScope(store.Node(node))
	p.decreaseIndentIf(indented)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) mayNeedDotDotForPropertyAccess(expression store.Node) bool {
	expression = store.SkipPartiallyEmittedExpressions(expression)
	if store.IsNumericLiteral(expression) {
		// check if numeric literal is a decimal literal that was originally written with a dot
		text := p.getLiteralTextOfNode(expression /*sourceFile*/, nil, getLiteralTextFlagsNeverAsciiEscape)
		// If the number will be printed verbatim and it doesn't already contain a dot or an exponent indicator, add one
		// if the expression doesn't have any comments that will be emitted.
		return expression.AsNumericLiteral().TokenFlags()&ast.TokenFlagsWithSpecifier == 0 &&
			!strings.Contains(text, scanner.TokenToString(ast.KindDotToken)) &&
			!strings.Contains(text, "E") &&
			!strings.Contains(text, "e")
	}
	return false
}

func (p *Printer) emitElementAccessExpression(node store.ElementAccessExpression) {
	state := p.enterNode(store.Node(node))
	p.emitExpression(node.Expression(), core.IfElse(store.IsOptionalChain(store.Node(node)), ast.OperatorPrecedenceOptionalChain, ast.OperatorPrecedenceMember))
	p.emitTokenNode(node.QuestionDotToken())
	p.emitToken(ast.KindOpenBracketToken, greatestEnd(-1, node.Expression(), node.QuestionDotToken()), WriteKindPunctuation, store.Node(node))
	p.emitExpression(node.ArgumentExpression(), ast.OperatorPrecedenceComma)
	p.emitToken(ast.KindCloseBracketToken, int(node.ArgumentExpression().End()), WriteKindPunctuation, store.Node(node))
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitArgument(node store.Node) {
	p.emitExpression(node, ast.OperatorPrecedenceSpread)
}

func (p *Printer) emitCallee(callee store.Node, parentNode store.Node) {
	if p.shouldEmitIndirectCall(parentNode) {
		p.writePunctuation("(")
		p.writeLiteral("0")
		p.writePunctuation(",")
		p.writeSpace()
		p.emitExpression(callee, ast.OperatorPrecedenceComma)
		p.writePunctuation(")")
	} else if parentNode.Kind() == ast.KindCallExpression && isNewExpressionWithoutArguments(store.SkipPartiallyEmittedExpressions(callee)) {
		// Parenthesize `new C` inside of a CallExpression so it is treated as `(new C)()` and not `new C()`
		p.emitExpression(callee, ast.OperatorPrecedenceParentheses)
	} else {
		p.emitExpression(callee, core.IfElse(store.IsOptionalChain(parentNode), ast.OperatorPrecedenceOptionalChain, ast.OperatorPrecedenceMember))
	}
}

func (p *Printer) emitCallExpression(node store.CallExpression) {
	state := p.enterNode(store.Node(node))
	p.emitCallee(node.Expression(), store.Node(node))
	p.emitTokenNode(node.QuestionDotToken())
	p.emitTypeArguments(store.Node(node), node.TypeArguments())
	p.emitList((*Printer).emitArgument, store.Node(node), node.Arguments(), LFCallExpressionArguments)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitNewExpression(node store.NewExpression) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindNewKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	if store.SkipPartiallyEmittedExpressions(node.Expression()).Kind() == ast.KindCallExpression {
		// Parenthesize `C()` inside of a NewExpression so it is treated as `new (C())` and not `new C()`
		p.emitExpression(node.Expression(), ast.OperatorPrecedenceParentheses)
	} else {
		p.emitExpression(node.Expression(), ast.OperatorPrecedenceMember)
	}
	p.emitTypeArguments(store.Node(node), node.TypeArguments())
	p.emitList((*Printer).emitArgument, store.Node(node), node.Arguments(), LFNewExpressionArguments)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitTemplateLiteral(node store.Node) {
	switch node.Kind() {
	case ast.KindNoSubstitutionTemplateLiteral:
		p.emitNoSubstitutionTemplateLiteral(node.AsNoSubstitutionTemplateLiteral())
	case ast.KindTemplateExpression:
		p.emitTemplateExpression(node.AsTemplateExpression())
	default:
		panic(fmt.Sprintf("unhandled TemplateLiteral: %v", node.Kind()))
	}
}

func (p *Printer) emitTaggedTemplateExpression(node store.TaggedTemplateExpression) {
	state := p.enterNode(store.Node(node))
	p.emitCallee(node.Tag(), store.Node(node))
	p.emitTypeArguments(store.Node(node), node.TypeArguments())
	p.writeSpace()
	p.emitTemplateLiteral(node.Template())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitTypeAssertionExpression(node store.TypeAssertion) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("<")
	p.emitTypeNodeOutsideExtends(node.Type())
	p.writePunctuation(">")
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceUpdate)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitParenthesizedExpression(node store.ParenthesizedExpression) {
	state := p.enterNode(store.Node(node))
	openParenPos := p.emitToken(ast.KindOpenParenToken, int(store.Node(node).Pos()), WriteKindPunctuation, store.Node(node))
	indented := p.writeLineSeparatorsAndIndentBefore(node.Expression(), store.Node(node))
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceComma)
	p.writeLineSeparatorsAfter(node.Expression(), store.Node(node))
	p.decreaseIndentIf(indented)
	closeParenPos := openParenPos
	if !node.Expression().IsNil() {
		closeParenPos = int(node.Expression().End())
	}
	p.emitToken(ast.KindCloseParenToken, closeParenPos, WriteKindPunctuation, store.Node(node))
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitFunctionExpression(node store.FunctionExpression) {
	state := p.enterNode(store.Node(node))
	p.generateNameIfNeeded(node.Name())
	p.emitModifierList(store.Node(node), node.Modifiers(), false /*allowDecorators*/)
	p.writeKeyword("function")
	p.emitTokenNode(node.AsteriskToken())
	p.writeSpace()
	p.emitIdentifierNameNode(node.Name())
	indented := p.shouldEmitIndented(store.Node(node))
	p.increaseIndentIf(indented)
	p.pushNameGenerationScope(store.Node(node))
	p.emitSignature(store.Node(node))
	p.emitFunctionBodyNode(node.Body())
	p.popNameGenerationScope(store.Node(node))
	p.decreaseIndentIf(indented)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitArrowFunction(node store.ArrowFunction) {
	state := p.enterNode(store.Node(node))
	p.emitModifierList(store.Node(node), node.Modifiers(), false /*allowDecorators*/)
	indented := p.shouldEmitIndented(store.Node(node))
	p.increaseIndentIf(indented)
	p.pushNameGenerationScope(store.Node(node))
	p.emitTypeParameters(store.Node(node), node.TypeParameters())
	p.emitParametersForArrow(store.Node(node), node.Parameters())
	p.emitTypeAnnotation(node.Type())
	p.writeSpace()
	p.emitTokenNode(node.EqualsGreaterThanToken())
	p.writeSpace()
	p.emitConciseBody(node.Body())
	p.popNameGenerationScope(store.Node(node))
	p.decreaseIndentIf(indented)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitDeleteExpression(node store.DeleteExpression) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindDeleteKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceUnary)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitTypeOfExpression(node store.TypeOfExpression) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindTypeOfKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceUnary)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitVoidExpression(node store.VoidExpression) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindVoidKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceUnary)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitAwaitExpression(node store.AwaitExpression) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindAwaitKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceUnary)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitPrefixUnaryExpression(node store.PrefixUnaryExpression) {
	state := p.enterNode(store.Node(node))
	operator := node.Operator()
	operand := node.Operand()
	p.emitToken(operator, int(store.Node(node).Pos()), WriteKindOperator, store.Node(node))

	// In some cases, we need to emit a space between the operator and the operand. One obvious case
	// is when the operator is an identifier, like delete or typeof. We also need to do this for plus
	// and minus expressions in certain cases. Specifically, consider the following two cases (parens
	// are just for clarity of exposition, and not part of the source code):
	//
	//  (+(+1))
	//  (+(++1))
	//
	// We need to emit a space in both cases. In the first case, the absence of a space will make
	// the resulting expression a prefix increment operation. And in the second, it will make the resulting
	// expression a prefix increment whose operand is a plus expression - (++(+x))
	// The same is true of minus of course.
	if operand.Kind() == ast.KindPrefixUnaryExpression {
		inner := operand.AsPrefixUnaryExpression().Operator()
		if (operator == ast.KindPlusToken && (inner == ast.KindPlusToken || inner == ast.KindPlusPlusToken)) ||
			(operator == ast.KindMinusToken && (inner == ast.KindMinusToken || inner == ast.KindMinusMinusToken)) {
			p.writeSpace()
		}
	}

	p.emitExpression(node.Operand(), ast.OperatorPrecedenceUnary)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitPostfixUnaryExpression(node store.PostfixUnaryExpression) {
	state := p.enterNode(store.Node(node))
	p.emitExpression(node.Operand(), ast.OperatorPrecedenceLeftHandSide)
	p.emitToken(node.Operator(), int(node.Operand().End()), WriteKindOperator, store.Node(node))
	p.exitNode(store.Node(node), state)
}

func (p *Printer) getLiteralKindOfBinaryPlusOperand(node store.Node) ast.Kind {
	node = store.SkipPartiallyEmittedExpressions(node)

	if ast.IsLiteralKind(node.Kind()) {
		return node.Kind()
	}

	if node.Kind() == ast.KindBinaryExpression {
		if n := node.AsBinaryExpression(); n.OperatorToken().Kind() == ast.KindPlusToken {
			// !!! Determine if caching this is worthwhile over recomputing
			////if n.cachedLiteralKind != KindUnknown {
			////	return n.cachedLiteralKind;
			////}

			leftKind := p.getLiteralKindOfBinaryPlusOperand(n.Left())
			literalKind := ast.KindUnknown
			if ast.IsLiteralKind(leftKind) && leftKind == p.getLiteralKindOfBinaryPlusOperand(n.Right()) {
				literalKind = leftKind
			}

			////n.cachedLiteralKind = literalKind;
			return literalKind
		}
	}

	return ast.KindUnknown
}

func (p *Printer) getBinaryExpressionPrecedence(node store.BinaryExpression) (leftPrec ast.OperatorPrecedence, rightPrec ast.OperatorPrecedence) {
	precedence := store.GetExpressionPrecedence(store.Node(node))
	leftPrec = precedence
	rightPrec = precedence
	switch precedence {
	case ast.OperatorPrecedenceComma:
		// No need to parenthesize the right operand when the binary operator and
		// operand are both ,:
		//  x,(a,b)     => x,a,b
		break
	case ast.OperatorPrecedenceAssignment:
		// assignment is right-associative
		leftPrec = ast.OperatorPrecedenceConditional
		rightPrec = ast.OperatorPrecedenceYield
	case ast.OperatorPrecedenceLogicalOR:
		rightPrec = ast.OperatorPrecedenceLogicalAND
	case ast.OperatorPrecedenceLogicalAND:
		rightPrec = ast.OperatorPrecedenceBitwiseOR
	case ast.OperatorPrecedenceBitwiseOR:
		// No need to parenthesize the right operand when the binary operator and
		// operand are both | due to the associative property of mathematics:
		//  x|(a|b)     => x|a|b
		break
	case ast.OperatorPrecedenceBitwiseXOR:
		// No need to parenthesize the right operand when the binary operator and
		// operand are both ^ due to the associative property of mathematics:
		//  x^(a^b)     => x^a^b
		break
	case ast.OperatorPrecedenceBitwiseAND:
		// No need to parenthesize the right operand when the binary operator and
		// operand are both & due to the associative property of mathematics:
		//  x&(a&b)     => x&a&b
		break
	case ast.OperatorPrecedenceEquality:
		rightPrec = ast.OperatorPrecedenceRelational
	case ast.OperatorPrecedenceRelational:
		rightPrec = ast.OperatorPrecedenceShift
	case ast.OperatorPrecedenceShift:
		rightPrec = ast.OperatorPrecedenceAdditive
	case ast.OperatorPrecedenceAdditive:
		if node.OperatorToken().Kind() == ast.KindPlusToken && isBinaryOperation(node.Right(), ast.KindPlusToken) {
			leftKind := p.getLiteralKindOfBinaryPlusOperand(node.Left())
			if ast.IsLiteralKind(leftKind) && leftKind == p.getLiteralKindOfBinaryPlusOperand(node.Right()) {
				// No need to parenthesize the right operand when the binary operator
				// is plus (+) if both the left and right operands consist solely of either
				// literals of the same kind or binary plus (+) expressions for literals of
				// the same kind (recursively).
				//  "a"+(1+2)       => "a"+(1+2)
				//  "a"+("b"+"c")   => "a"+"b"+"c"
				break
			}
		}
		rightPrec = ast.OperatorPrecedenceMultiplicative
	case ast.OperatorPrecedenceMultiplicative:
		if node.OperatorToken().Kind() == ast.KindAsteriskToken && isBinaryOperation(node.Right(), ast.KindAsteriskToken) {
			// No need to parenthesize the right operand when the binary operator and
			// operand are both * due to the associative property of mathematics:
			//  x*(a*b)     => x*a*b
			break
		}
		rightPrec = ast.OperatorPrecedenceExponentiation
	case ast.OperatorPrecedenceExponentiation:
		// exponentiation is right-associative
		leftPrec = ast.OperatorPrecedenceUpdate
	default:
		panic(fmt.Sprintf("unhandled precedence: %v", precedence))
	}
	return leftPrec, rightPrec
}

func (p *Printer) emitBinaryExpression(node store.BinaryExpression) {
	leftPrec, rightPrec := p.getBinaryExpressionPrecedence(node)
	if emittedLeft := store.SkipPartiallyEmittedExpressions(node.Left()); store.NodeIsSynthesized(emittedLeft) && emittedLeft.Kind() == ast.KindBinaryExpression && mixingBinaryOperatorsRequiresParentheses(node.OperatorToken().Kind(), emittedLeft.AsBinaryExpression().OperatorToken().Kind()) {
		leftPrec = ast.OperatorPrecedenceHighest
	}
	if emittedRight := store.SkipPartiallyEmittedExpressions(node.Right()); store.NodeIsSynthesized(emittedRight) && emittedRight.Kind() == ast.KindBinaryExpression && mixingBinaryOperatorsRequiresParentheses(node.OperatorToken().Kind(), emittedRight.AsBinaryExpression().OperatorToken().Kind()) {
		rightPrec = ast.OperatorPrecedenceHighest
	}
	state := p.enterNode(store.Node(node))
	p.emitExpression(node.Left(), leftPrec)
	linesBeforeOperator := p.getLinesBetweenNodes(store.Node(node), node.Left(), node.OperatorToken())
	linesAfterOperator := p.getLinesBetweenNodes(store.Node(node), node.OperatorToken(), node.Right())
	p.writeLinesAndIndent(linesBeforeOperator, node.OperatorToken().Kind() != ast.KindCommaToken /*writeSpaceIfNotIndenting*/)
	p.emitTokenNodeEx(node.OperatorToken(), tefNoSourceMaps)
	p.writeLinesAndIndent(linesAfterOperator, true /*writeSpaceIfNotIndenting*/) // Binary operators should have a space before the comment starts
	p.emitExpression(node.Right(), rightPrec)
	p.decreaseIndentIf(linesAfterOperator > 0)
	p.decreaseIndentIf(linesBeforeOperator > 0)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitShortCircuitExpression(node store.Node) {
	if isBinaryOperation(store.SkipPartiallyEmittedExpressions(node), ast.KindQuestionQuestionToken) {
		p.emitExpression(node, ast.OperatorPrecedenceCoalesce)
	} else {
		p.emitExpression(node, ast.OperatorPrecedenceLogicalOR)
	}
}

func (p *Printer) emitConditionalExpression(node store.ConditionalExpression) {
	state := p.enterNode(store.Node(node))
	linesBeforeQuestion := p.getLinesBetweenNodes(store.Node(node), node.Condition(), node.QuestionToken())
	linesAfterQuestion := p.getLinesBetweenNodes(store.Node(node), node.QuestionToken(), node.WhenTrue())
	linesBeforeColon := p.getLinesBetweenNodes(store.Node(node), node.WhenTrue(), node.ColonToken())
	linesAfterColon := p.getLinesBetweenNodes(store.Node(node), node.ColonToken(), node.WhenFalse())
	p.emitShortCircuitExpression(node.Condition())
	p.writeLinesAndIndent(linesBeforeQuestion /*writeSpaceIfNotIndenting*/, true)
	p.emitPunctuationNode(node.QuestionToken())
	p.writeLinesAndIndent(linesAfterQuestion /*writeSpaceIfNotIndenting*/, true)
	p.emitExpression(node.WhenTrue(), ast.OperatorPrecedenceYield)
	p.decreaseIndentIf(linesAfterQuestion > 0)
	p.decreaseIndentIf(linesBeforeQuestion > 0)
	p.writeLinesAndIndent(linesBeforeColon /*writeSpaceIfNotIndenting*/, true)
	p.emitPunctuationNode(node.ColonToken())
	p.writeLinesAndIndent(linesAfterColon /*writeSpaceIfNotIndenting*/, true)
	p.emitExpression(node.WhenFalse(), ast.OperatorPrecedenceYield)
	p.decreaseIndentIf(linesAfterColon > 0)
	p.decreaseIndentIf(linesBeforeColon > 0)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitTemplateExpression(node store.TemplateExpression) {
	state := p.enterNode(store.Node(node))
	p.emitTemplateHead(node.Head().AsTemplateHead())
	p.emitList((*Printer).emitTemplateSpanNode, store.Node(node), node.TemplateSpans(), LFTemplateExpressionSpans)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitYieldExpression(node store.YieldExpression) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindYieldKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.emitPunctuationNode(node.AsteriskToken())
	if !node.Expression().IsNil() {
		p.writeSpace()
		p.emitExpressionNoASI(node.Expression(), ast.OperatorPrecedenceDisallowComma)
	}
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitSpreadElement(node store.SpreadElement) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindDotDotDotToken, int(store.Node(node).Pos()), WriteKindPunctuation, store.Node(node))
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceDisallowComma)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitClassExpression(node store.ClassExpression) {
	state := p.enterNode(store.Node(node))
	p.generateNameIfNeeded(node.Name())

	pos := p.emitModifierList(store.Node(node), node.Modifiers(), true /*allowDecorators*/)
	p.emitToken(ast.KindClassKeyword, pos, WriteKindKeyword, store.Node(node))

	if !node.Name().IsNil() {
		p.writeSpace()
		p.emitIdentifierName(node.Name().AsIdentifier())
	}

	indented := p.shouldEmitIndented(store.Node(node))
	p.increaseIndentIf(indented)

	p.emitTypeParameters(store.Node(node), node.TypeParameters())
	p.emitList((*Printer).emitHeritageClauseNode, store.Node(node), node.HeritageClauses(), LFClassHeritageClauses)
	p.writeSpace()
	p.writePunctuation("{")
	p.pushNameGenerationScope(store.Node(node))
	p.generateAllMemberNames(node.Members())
	p.emitList((*Printer).emitClassElement, store.Node(node), node.Members(), LFClassMembers)
	p.popNameGenerationScope(store.Node(node))
	p.writePunctuation("}")

	p.decreaseIndentIf(indented)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitOmittedExpression(node store.Node) {
	p.exitNode(node, p.enterNode(node))
}

func (p *Printer) emitExpressionWithTypeArguments(node store.ExpressionWithTypeArguments) {
	state := p.enterNode(store.Node(node))
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceMember)
	p.emitTypeArguments(store.Node(node), node.TypeArguments())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitAsExpression(node store.AsExpression) {
	state := p.enterNode(store.Node(node))
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceRelational)
	p.writeSpace()
	p.writeKeyword("as")
	p.writeSpace()
	p.emitTypeNodeOutsideExtends(node.Type())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitSatisfiesExpression(node store.SatisfiesExpression) {
	state := p.enterNode(store.Node(node))
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceRelational)
	p.writeSpace()
	p.writeKeyword("satisfies")
	p.writeSpace()
	p.emitTypeNodeOutsideExtends(node.Type())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitNonNullExpression(node store.NonNullExpression) {
	state := p.enterNode(store.Node(node))
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceMember)
	p.writeOperator("!")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitMetaProperty(node store.MetaProperty) {
	state := p.enterNode(store.Node(node))
	p.emitToken(node.KeywordToken(), int(store.Node(node).Pos()), WriteKindPunctuation, store.Node(node))
	p.writePunctuation(".")
	p.emitIdentifierName(node.Name().AsIdentifier())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitPartiallyEmittedExpression(node store.PartiallyEmittedExpression) {
	// avoid reprinting parens for nested partially emitted expressions
	type entry struct {
		node  store.PartiallyEmittedExpression
		state printerState
	}
	var stack core.Stack[entry]
	for {
		state := p.enterNode(store.Node(node))
		emitFlags := p.emitContext.EmitFlags(store.Node(node))
		if emitFlags&EFNoLeadingComments == 0 && store.Node(node).Pos() != node.Expression().Pos() {
			p.emitTrailingCommentsOfPosition(int(node.Expression().Pos()), false /*prefixSpace*/, false /*forceNoNewline*/)
		}
		stack.Push(entry{node, state})
		if !store.IsPartiallyEmittedExpression(node.Expression()) {
			break
		}
		node = node.Expression().AsPartiallyEmittedExpression()
	}

	p.emitExpression(node.Expression(), ast.OperatorPrecedenceLowest)

	// unwind stack
	for stack.Len() > 0 {
		entry := stack.Pop()
		emitFlags := p.emitContext.EmitFlags(store.Node(node))
		if emitFlags&EFNoTrailingComments == 0 && store.Node(node).End() != node.Expression().End() {
			p.emitLeadingCommentsOfPosition(int(node.Expression().End()))
		}
		p.exitNode(store.Node(node), entry.state)
		node = entry.node
	}
}

func (p *Printer) commentWillEmitNewLine(comment ast.CommentRange) bool {
	return comment.Kind == ast.KindSingleLineCommentTrivia || comment.HasTrailingNewLine
}

func (p *Printer) syntheticCommentWillEmitNewLine(comment SynthesizedComment) bool {
	return comment.Kind == ast.KindSingleLineCommentTrivia || comment.HasTrailingNewLine
}

func (p *Printer) willEmitLeadingNewLine(node store.Node) bool {
	if p.currentSourceFile == nil {
		return false
	}
	hasLeadingCommentRanges := false
	hasNewLineComment := false
	for comment := range storescanner.GetLeadingCommentRanges(p.emitContext.Factory.Factory, p.currentSourceFile.Text(), int(node.Pos())) {
		hasLeadingCommentRanges = true
		if p.commentWillEmitNewLine(comment) {
			hasNewLineComment = true
		}
	}
	if hasLeadingCommentRanges {
		parseNode := p.emitContext.ParseNode(node)
		if !parseNode.IsNil() && store.IsParenthesizedExpression(parseNode.Parent()) {
			return true
		}
	}
	if hasNewLineComment {
		return true
	}
	if slices.ContainsFunc(p.emitContext.GetSyntheticLeadingComments(node), p.syntheticCommentWillEmitNewLine) {
		return true
	}
	if store.IsPartiallyEmittedExpression(node) {
		pee := node.AsPartiallyEmittedExpression()
		if node.Pos() != pee.Expression().Pos() {
			for comment := range storescanner.GetTrailingCommentRanges(p.emitContext.Factory.Factory, p.currentSourceFile.Text(), int(pee.Expression().Pos())) {
				if p.commentWillEmitNewLine(comment) {
					return true
				}
			}
		}
		return p.willEmitLeadingNewLine(pee.Expression())
	}
	return false
}

func (p *Printer) emitExpressionNoASI(node store.Node, precedence ast.OperatorPrecedence) {
	node = p.parenthesizeExpressionForNoAsi(node)
	p.emitExpression(node, precedence)
}

func (p *Printer) emitExpression(node store.Node, precedence ast.OperatorPrecedence) {
	parens := store.GetExpressionPrecedence(store.SkipPartiallyEmittedExpressions(node)) < precedence
	if parens {
		p.writePunctuation("(")
	}

	switch node.Kind() {
	// Keywords
	case ast.KindTrueKeyword, ast.KindFalseKeyword, ast.KindNullKeyword:
		p.emitTokenNode(node)
	case ast.KindThisKeyword, ast.KindSuperKeyword, ast.KindImportKeyword:
		p.emitKeywordExpression(node)

	// Literals
	case ast.KindNumericLiteral:
		p.emitNumericLiteral(node.AsNumericLiteral())
	case ast.KindBigIntLiteral:
		p.emitBigIntLiteral(node.AsBigIntLiteral())
	case ast.KindStringLiteral:
		p.emitStringLiteral(node.AsStringLiteral())
	case ast.KindRegularExpressionLiteral:
		p.emitRegularExpressionLiteral(node.AsRegularExpressionLiteral())
	case ast.KindNoSubstitutionTemplateLiteral:
		p.emitNoSubstitutionTemplateLiteral(node.AsNoSubstitutionTemplateLiteral())

	// Identifiers
	case ast.KindIdentifier:
		p.emitIdentifierReference(node.AsIdentifier())
	case ast.KindPrivateIdentifier:
		p.emitPrivateIdentifier(node.AsPrivateIdentifier())

	// Expressions
	case ast.KindArrayLiteralExpression:
		p.emitArrayLiteralExpression(node.AsArrayLiteralExpression())
	case ast.KindObjectLiteralExpression:
		p.emitObjectLiteralExpression(node.AsObjectLiteralExpression())
	case ast.KindPropertyAccessExpression:
		p.emitPropertyAccessExpression(node.AsPropertyAccessExpression())
	case ast.KindElementAccessExpression:
		p.emitElementAccessExpression(node.AsElementAccessExpression())
	case ast.KindCallExpression:
		p.emitCallExpression(node.AsCallExpression())
	case ast.KindNewExpression:
		p.emitNewExpression(node.AsNewExpression())
	case ast.KindTaggedTemplateExpression:
		p.emitTaggedTemplateExpression(node.AsTaggedTemplateExpression())
	case ast.KindTypeAssertionExpression:
		p.emitTypeAssertionExpression(node.AsTypeAssertion())
	case ast.KindParenthesizedExpression:
		p.emitParenthesizedExpression(node.AsParenthesizedExpression())
	case ast.KindFunctionExpression:
		p.emitFunctionExpression(node.AsFunctionExpression())
	case ast.KindArrowFunction:
		p.emitArrowFunction(node.AsArrowFunction())
	case ast.KindDeleteExpression:
		p.emitDeleteExpression(node.AsDeleteExpression())
	case ast.KindTypeOfExpression:
		p.emitTypeOfExpression(node.AsTypeOfExpression())
	case ast.KindVoidExpression:
		p.emitVoidExpression(node.AsVoidExpression())
	case ast.KindAwaitExpression:
		p.emitAwaitExpression(node.AsAwaitExpression())
	case ast.KindPrefixUnaryExpression:
		p.emitPrefixUnaryExpression(node.AsPrefixUnaryExpression())
	case ast.KindPostfixUnaryExpression:
		p.emitPostfixUnaryExpression(node.AsPostfixUnaryExpression())
	case ast.KindBinaryExpression:
		p.emitBinaryExpression(node.AsBinaryExpression())
	case ast.KindConditionalExpression:
		p.emitConditionalExpression(node.AsConditionalExpression())
	case ast.KindTemplateExpression:
		p.emitTemplateExpression(node.AsTemplateExpression())
	case ast.KindYieldExpression:
		p.emitYieldExpression(node.AsYieldExpression())
	case ast.KindSpreadElement:
		p.emitSpreadElement(node.AsSpreadElement())
	case ast.KindClassExpression:
		p.emitClassExpression(node.AsClassExpression())
	case ast.KindOmittedExpression:
		p.emitOmittedExpression(node)
	case ast.KindAsExpression:
		p.emitAsExpression(node.AsAsExpression())
	case ast.KindNonNullExpression:
		p.emitNonNullExpression(node.AsNonNullExpression())
	case ast.KindExpressionWithTypeArguments:
		p.emitExpressionWithTypeArguments(node.AsExpressionWithTypeArguments())
	case ast.KindSatisfiesExpression:
		p.emitSatisfiesExpression(node.AsSatisfiesExpression())
	case ast.KindMetaProperty:
		p.emitMetaProperty(node.AsMetaProperty())
	case ast.KindSyntheticExpression:
		panic("SyntheticExpression should never be printed.")
	case ast.KindMissingDeclaration:
		break

	// JSX
	case ast.KindJsxElement:
		p.emitJsxElement(node.AsJsxElement())
	case ast.KindJsxSelfClosingElement:
		p.emitJsxSelfClosingElement(node.AsJsxSelfClosingElement())
	case ast.KindJsxFragment:
		p.emitJsxFragment(node.AsJsxFragment())

	// Synthesized list
	case ast.KindSyntaxList:
		panic("SyntaxList should not be printed")

	// Transformation nodes
	case ast.KindNotEmittedStatement:
		return
	case ast.KindPartiallyEmittedExpression:
		p.emitPartiallyEmittedExpression(node.AsPartiallyEmittedExpression())
	case ast.KindSyntheticReferenceExpression:
		panic("SyntheticReferenceExpression should not be printed")

	default:
		panic(fmt.Sprintf("unexpected Expression: %v", node.Kind()))
	}

	if parens {
		p.writePunctuation(")")
	}
}

func (p *Printer) emitTemplateSpan(node store.TemplateSpan) {
	state := p.enterNode(store.Node(node))
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceComma)
	p.emitTemplateMiddleTail(node.Literal())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitTemplateSpanNode(node store.Node) {
	p.emitTemplateSpan(node.AsTemplateSpan())
}

func (p *Printer) emitSemicolonClassElement(node store.Node) {
	state := p.enterNode(node)
	p.writeTrailingSemicolon()
	p.exitNode(node, state)
}

func (p *Printer) isEmptyBlock(block store.Node, statements store.List) bool {
	return statements.Len() == 0 &&
		(p.currentSourceFile == nil || rangeEndIsOnSameLineAsRangeStart(block.Loc(), block.Loc(), p.currentSourceFile))
}

func (p *Printer) emitBlock(node store.Block) {
	state := p.enterNode(store.Node(node))
	p.generateNames(store.Node(node))
	p.emitToken(ast.KindOpenBraceToken, int(store.Node(node).Pos()), WriteKindPunctuation, store.Node(node))

	format := core.IfElse(!node.MultiLine() && p.isEmptyBlock(store.Node(node), node.Statements()) || p.shouldEmitOnSingleLine(store.Node(node)),
		LFSingleLineBlockStatements,
		LFMultiLineBlockStatements)
	p.emitList((*Printer).emitStatement, store.Node(node), node.Statements(), format)

	p.emitTokenEx(ast.KindCloseBraceToken, int(node.Statements().End()), WriteKindPunctuation, store.Node(node), core.IfElse(format&LFMultiLine != 0, tefIndentLeadingComments, tefNone))
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitVariableStatement(node store.VariableStatement) {
	state := p.enterNode(store.Node(node))
	p.emitModifierList(store.Node(node), node.Modifiers(), false /*allowDecorators*/)
	p.emitVariableDeclarationList(node.DeclarationList().AsVariableDeclarationList())
	p.writeTrailingSemicolon()
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitEmptyStatement(node store.Node, isEmbeddedStatement bool) {
	state := p.enterNode(node)

	// While most trailing semicolons are possibly insignificant, an embedded "empty"
	// statement is significant and cannot be elided by a trailing-semicolon-omitting writer.
	if isEmbeddedStatement {
		p.writePunctuation(";")
	} else {
		p.writeTrailingSemicolon()
	}
	p.exitNode(node, state)
}

func (p *Printer) emitExpressionStatement(node store.ExpressionStatement) {
	state := p.enterNode(store.Node(node))

	if p.currentSourceFile != nil && p.currentSourceFile.ScriptKind == core.ScriptKindJSON {
		// !!! In strada, this was handled by an undefined parenthesizerRule, so this is a hack.
		p.emitExpression(node.Expression(), ast.OperatorPrecedenceComma)
	} else if isImmediatelyInvokedFunctionExpressionOrArrowFunction(node.Expression()) {
		// For IIFEs, parenthesize just the callee (not the whole call), matching TypeScript's
		// parenthesizeExpressionOfExpressionStatement which wraps the function/arrow in parens:
		//   (function() { })()  -- not (function() { }())
		p.emitIIFEWithParenthesizedCallee(node.Expression())
	} else {
		switch store.GetLeftmostExpression(node.Expression(), false /*stopAtCallExpression*/).Kind() {
		case ast.KindFunctionExpression, ast.KindObjectLiteralExpression:
			p.emitExpression(node.Expression(), ast.OperatorPrecedenceParentheses)
		default:
			p.emitExpression(node.Expression(), ast.OperatorPrecedenceComma)
		}
	}

	// Emit semicolon in non json files
	// or if json file that created synthesized expression(eg.define expression statement when --out and amd code generation)
	if p.currentSourceFile == nil ||
		p.currentSourceFile.ScriptKind != core.ScriptKindJSON ||
		store.NodeIsSynthesized(node.Expression()) {
		p.writeTrailingSemicolon()
	}

	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitIIFEWithParenthesizedCallee(node store.Node) {
	// Walk through PartiallyEmittedExpression wrappers to find the call
	call := store.SkipPartiallyEmittedExpressions(node).AsCallExpression()
	state := p.enterNode(store.Node(call))
	// Emit the callee wrapped in parens
	p.writePunctuation("(")
	p.emitExpression(call.Expression(), ast.OperatorPrecedenceLowest)
	p.writePunctuation(")")
	p.emitTokenNode(call.QuestionDotToken())
	p.emitTypeArguments(store.Node(call), call.TypeArguments())
	p.emitList((*Printer).emitArgument, store.Node(call), call.Arguments(), LFCallExpressionArguments)
	p.exitNode(store.Node(call), state)
}

func (p *Printer) emitIfStatement(node store.IfStatement) {
	state := p.enterNode(store.Node(node))
	pos := p.emitToken(ast.KindIfKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitToken(ast.KindOpenParenToken, pos, WriteKindPunctuation, store.Node(node))
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceLowest)
	p.emitToken(ast.KindCloseParenToken, int(node.Expression().End()), WriteKindPunctuation, store.Node(node))
	p.emitEmbeddedStatement(store.Node(node), node.ThenStatement())
	if !node.ElseStatement().IsNil() {
		p.writeLineOrSpace(store.Node(node), node.ThenStatement(), node.ElseStatement())
		p.emitToken(ast.KindElseKeyword, int(node.ThenStatement().End()), WriteKindKeyword, store.Node(node))
		if node.ElseStatement().Kind() == ast.KindIfStatement {
			p.writeSpace()
			p.emitIfStatement(node.ElseStatement().AsIfStatement())
		} else {
			p.emitEmbeddedStatement(store.Node(node), node.ElseStatement())
		}
	}
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitWhileClause(node store.Node, expression store.Node, startPos int) {
	pos := p.emitToken(ast.KindWhileKeyword, startPos, WriteKindKeyword, node)
	p.writeSpace()
	p.emitToken(ast.KindOpenParenToken, pos, WriteKindPunctuation, node)
	p.emitExpression(expression, ast.OperatorPrecedenceLowest)
	p.emitToken(ast.KindCloseParenToken, int(expression.End()), WriteKindPunctuation, node)
}

func (p *Printer) emitDoStatement(node store.DoStatement) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindDoKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.emitEmbeddedStatement(store.Node(node), node.Statement())
	if store.IsBlock(node.Statement()) && !p.Options.PreserveSourceNewlines {
		p.writeSpace()
	} else {
		p.writeLineOrSpace(store.Node(node), node.Statement(), node.Expression())
	}

	p.emitWhileClause(store.Node(node), node.Expression(), int(node.Statement().End()))
	p.writeTrailingSemicolon()
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitWhileStatement(node store.WhileStatement) {
	state := p.enterNode(store.Node(node))
	p.emitWhileClause(store.Node(node), node.Expression(), int(store.Node(node).Pos()))
	p.emitEmbeddedStatement(store.Node(node), node.Statement())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitForInitializer(node store.Node) {
	if node.Kind() == ast.KindVariableDeclarationList {
		p.emitVariableDeclarationList(node.AsVariableDeclarationList())
	} else {
		p.emitExpression(node, ast.OperatorPrecedenceLowest)
	}
}

func (p *Printer) emitForStatement(node store.ForStatement) {
	state := p.enterNode(store.Node(node))
	pos := p.emitToken(ast.KindForKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	pos = p.emitToken(ast.KindOpenParenToken, pos, WriteKindPunctuation, store.Node(node))
	if !node.Initializer().IsNil() {
		p.emitForInitializer(node.Initializer())
		pos = int(node.Initializer().End())
	}
	pos = p.emitToken(ast.KindSemicolonToken, pos, WriteKindPunctuation, store.Node(node))
	if !node.Condition().IsNil() {
		p.writeSpace()
		p.emitExpression(node.Condition(), ast.OperatorPrecedenceLowest)
		pos = int(node.Condition().End())
	}
	pos = p.emitToken(ast.KindSemicolonToken, pos, WriteKindPunctuation, store.Node(node))
	if !node.Incrementor().IsNil() {
		p.writeSpace()
		p.emitExpression(node.Incrementor(), ast.OperatorPrecedenceLowest)
		pos = int(node.Incrementor().End())
	}
	p.emitToken(ast.KindCloseParenToken, pos, WriteKindPunctuation, store.Node(node))
	p.emitEmbeddedStatement(store.Node(node), node.Statement())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitForInStatement(node store.ForInOrOfStatement) {
	state := p.enterNode(store.Node(node))
	pos := p.emitToken(ast.KindForKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitToken(ast.KindOpenParenToken, pos, WriteKindPunctuation, store.Node(node))
	p.emitForInitializer(node.Initializer())
	p.writeSpace()
	p.emitToken(ast.KindInKeyword, int(node.Initializer().End()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceLowest)
	p.emitToken(ast.KindCloseParenToken, int(node.Expression().End()), WriteKindPunctuation, store.Node(node))
	p.emitEmbeddedStatement(store.Node(node), node.Statement())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitForOfStatement(node store.ForInOrOfStatement) {
	state := p.enterNode(store.Node(node))
	openParenPos := p.emitToken(ast.KindForKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	if !node.AwaitModifier().IsNil() {
		p.emitKeywordNode(node.AwaitModifier())
		p.writeSpace()
	}
	p.emitToken(ast.KindOpenParenToken, openParenPos, WriteKindPunctuation, store.Node(node))
	p.emitForInitializer(node.Initializer())
	p.writeSpace()
	p.emitToken(ast.KindOfKeyword, int(node.Initializer().End()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceLowest)
	p.emitToken(ast.KindCloseParenToken, int(node.Expression().End()), WriteKindPunctuation, store.Node(node))
	p.emitEmbeddedStatement(store.Node(node), node.Statement())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitContinueStatement(node store.ContinueStatement) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindContinueKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	if !node.Label().IsNil() {
		p.writeSpace()
		p.emitLabelIdentifier(node.Label().AsIdentifier())
	}
	p.writeTrailingSemicolon()
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitBreakStatement(node store.BreakStatement) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindBreakKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	if !node.Label().IsNil() {
		p.writeSpace()
		p.emitLabelIdentifier(node.Label().AsIdentifier())
	}
	p.writeTrailingSemicolon()
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitReturnStatement(node store.ReturnStatement) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindReturnKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	if !node.Expression().IsNil() {
		p.writeSpace()
		p.emitExpressionNoASI(node.Expression(), ast.OperatorPrecedenceLowest)
	}
	p.writeTrailingSemicolon()
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitWithStatement(node store.WithStatement) {
	state := p.enterNode(store.Node(node))
	pos := p.emitToken(ast.KindWithKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitToken(ast.KindOpenParenToken, pos, WriteKindPunctuation, store.Node(node))
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceLowest)
	p.emitToken(ast.KindCloseParenToken, int(node.Expression().End()), WriteKindPunctuation, store.Node(node))
	p.emitEmbeddedStatement(store.Node(node), node.Statement())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitSwitchStatement(node store.SwitchStatement) {
	state := p.enterNode(store.Node(node))
	pos := p.emitToken(ast.KindSwitchKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitToken(ast.KindOpenParenToken, pos, WriteKindPunctuation, store.Node(node))
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceLowest)
	p.emitToken(ast.KindCloseParenToken, int(node.Expression().End()), WriteKindPunctuation, store.Node(node))
	p.writeSpace()
	p.emitCaseBlock(node.CaseBlock().AsCaseBlock())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitLabeledStatement(node store.LabeledStatement) {
	state := p.enterNode(store.Node(node))
	p.emitLabelIdentifier(node.Label().AsIdentifier())
	p.emitToken(ast.KindColonToken, int(node.Label().End()), WriteKindPunctuation, store.Node(node))

	// TODO: use emitEmbeddedStatement rather than writeSpace/emitStatement here after Strada migration as it is
	//       more consistent with similar emit elsewhere. writeSpace/emitStatement is used here to reduce spurious
	//       diffs when testing the Strada migration.
	////p.emitEmbeddedStatement(node.AsNode(), node.Statement)

	p.writeSpace()
	p.emitStatement(node.Statement())

	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitThrowStatement(node store.ThrowStatement) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindThrowKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitExpressionNoASI(node.Expression(), ast.OperatorPrecedenceLowest)
	p.writeTrailingSemicolon()
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitTryStatement(node store.TryStatement) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindTryKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitBlock(node.TryBlock().AsBlock())
	if !node.CatchClause().IsNil() {
		p.writeLineOrSpace(store.Node(node), node.TryBlock(), node.CatchClause())
		p.emitCatchClause(node.CatchClause().AsCatchClause())
	}
	if !node.FinallyBlock().IsNil() {
		p.writeLineOrSpace(store.Node(node), store.Coalesce(node.CatchClause(), node.TryBlock()), node.FinallyBlock())
		p.emitToken(ast.KindFinallyKeyword, int(store.Coalesce(node.CatchClause(), node.TryBlock()).End()), WriteKindKeyword, store.Node(node))
		p.writeSpace()
		p.emitBlock(node.FinallyBlock().AsBlock())
	}
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitDebuggerStatement(node store.Node) {
	state := p.enterNode(node)
	p.emitToken(ast.KindDebuggerKeyword, int(node.Pos()), WriteKindKeyword, node)
	p.writeTrailingSemicolon()
	p.exitNode(node, state)
}

func (p *Printer) emitNotEmittedStatement(node store.Node) {
	p.exitNode(node, p.enterNode(node))
}

func (p *Printer) emitNotEmittedTypeElement(node store.Node) {
	p.exitNode(node, p.enterNode(node))
}

func (p *Printer) emitVariableDeclaration(node store.VariableDeclaration) {
	state := p.enterNode(store.Node(node))
	p.emitBindingName(node.Name())
	p.emitPunctuationNode(node.ExclamationToken())
	p.emitTypeAnnotation(node.Type())
	p.emitInitializer(node.Initializer(), greatestEnd(int(node.Name().End()), node.Type(), p.emitContext.GetTypeNode(node.Name())), store.Node(node))
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitVariableDeclarationNode(node store.Node) {
	p.emitVariableDeclaration(node.AsVariableDeclaration())
}

func (p *Printer) emitVariableDeclarationList(node store.VariableDeclarationList) {
	state := p.enterNode(store.Node(node))
	switch {
	case store.IsVarLet(store.Node(node)):
		p.writeKeyword("let")
	case store.IsVarConst(store.Node(node)):
		p.writeKeyword("const")
	case store.IsVarUsing(store.Node(node)):
		p.writeKeyword("using")
	case store.IsVarAwaitUsing(store.Node(node)):
		p.writeKeyword("await")
		p.writeSpace()
		p.writeKeyword("using")
	default:
		p.writeKeyword("var")
	}
	p.writeSpace()
	p.emitList((*Printer).emitVariableDeclarationNode, store.Node(node), node.Declarations(), LFVariableDeclarationList)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitFunctionDeclaration(node store.FunctionDeclaration) {
	state := p.enterNode(store.Node(node))
	p.generateNameIfNeeded(node.Name())
	p.emitModifierList(store.Node(node), node.Modifiers(), false /*allowDecorators*/)
	p.writeKeyword("function")
	p.emitTokenNode(node.AsteriskToken())
	p.writeSpace()
	if name := node.Name(); !name.IsNil() {
		p.emitIdentifierName(name.AsIdentifier())
	}
	indented := p.shouldEmitIndented(store.Node(node))
	p.increaseIndentIf(indented)
	p.pushNameGenerationScope(store.Node(node))
	p.emitSignature(store.Node(node))
	p.emitFunctionBodyNode(node.Body())
	p.popNameGenerationScope(store.Node(node))
	p.decreaseIndentIf(indented)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitClassDeclaration(node store.ClassDeclaration) {
	state := p.enterNode(store.Node(node))
	p.generateNameIfNeeded(node.Name())
	pos := p.emitModifierList(store.Node(node), node.Modifiers(), true /*allowDecorators*/)
	p.emitToken(ast.KindClassKeyword, pos, WriteKindKeyword, store.Node(node))
	if !node.Name().IsNil() {
		p.writeSpace()
		p.emitIdentifierName(node.Name().AsIdentifier())
	}
	indented := p.shouldEmitIndented(store.Node(node))
	p.increaseIndentIf(indented)
	p.emitTypeParameters(store.Node(node), node.TypeParameters())
	p.emitList((*Printer).emitHeritageClauseNode, store.Node(node), node.HeritageClauses(), LFClassHeritageClauses)
	p.writeSpace()
	p.writePunctuation("{")
	p.pushNameGenerationScope(store.Node(node))
	p.generateAllMemberNames(node.Members())
	p.emitList((*Printer).emitClassElement, store.Node(node), node.Members(), LFClassMembers)
	p.popNameGenerationScope(store.Node(node))
	p.writePunctuation("}")
	p.decreaseIndentIf(indented)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitInterfaceDeclaration(node store.InterfaceDeclaration) {
	state := p.enterNode(store.Node(node))
	p.emitModifierList(store.Node(node), node.Modifiers(), false /*allowDecorators*/)
	p.writeKeyword("interface")
	p.writeSpace()
	p.emitBindingIdentifier(node.Name().AsIdentifier())
	p.emitTypeParameters(store.Node(node), node.TypeParameters())
	p.emitList((*Printer).emitHeritageClauseNode, store.Node(node), node.HeritageClauses(), LFHeritageClauses)
	p.writeSpace()
	p.writePunctuation("{")
	p.pushNameGenerationScope(store.Node(node))
	p.generateAllMemberNames(node.Members())
	p.emitList((*Printer).emitTypeElement, store.Node(node), node.Members(), LFInterfaceMembers)
	p.popNameGenerationScope(store.Node(node))
	p.writePunctuation("}")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitTypeAliasDeclaration(node store.TypeAliasDeclaration) {
	state := p.enterNode(store.Node(node))
	p.emitModifierList(store.Node(node), node.Modifiers(), false /*allowDecorators*/)
	p.writeKeyword("type")
	p.writeSpace()
	p.emitBindingIdentifier(node.Name().AsIdentifier())
	p.emitTypeParameters(store.Node(node), node.TypeParameters())
	p.writeSpace()
	p.writePunctuation("=")
	p.writeSpace()
	p.emitTypeNodeOutsideExtends(node.Type())
	p.writeTrailingSemicolon()
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitEnumDeclaration(node store.EnumDeclaration) {
	state := p.enterNode(store.Node(node))
	p.emitModifierList(store.Node(node), node.Modifiers(), false /*allowDecorators*/)
	p.writeKeyword("enum")
	p.writeSpace()
	p.emitBindingIdentifier(node.Name().AsIdentifier())
	p.writeSpace()
	p.writePunctuation("{")
	p.emitList((*Printer).emitEnumMemberNode, store.Node(node), node.Members(), LFEnumMembers)
	p.writePunctuation("}")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitModuleDeclaration(node store.ModuleDeclaration) {
	state := p.enterNode(store.Node(node))
	p.emitModifierList(store.Node(node), node.Modifiers(), false /*allowDecorators*/)
	if node.Keyword() != ast.KindGlobalKeyword {
		p.writeKeyword(core.IfElse(node.Keyword() == ast.KindNamespaceKeyword, "namespace", "module"))
		p.writeSpace()
	}
	p.emitModuleName(node.Name())
	body := node.Body()
	for !body.IsNil() && store.IsModuleDeclaration(body) {
		module := body.AsModuleDeclaration()
		p.writePunctuation(".")
		p.emitNestedModuleName(module.Name())
		body = module.Body()
	}
	if !node.Attributes().IsNil() {
		p.writeSpace()
		p.writeKeyword("with")
		p.writeSpace()
		p.emitTypeNode(node.Attributes(), ast.TypePrecedenceNonArray)
	}
	if body.IsNil() {
		p.writeTrailingSemicolon()
	} else {
		p.writeSpace()
		p.emitModuleBlock(body.AsModuleBlock())
	}
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitModuleBlock(node store.ModuleBlock) {
	state := p.enterNode(store.Node(node))
	p.generateNames(store.Node(node))
	p.emitToken(ast.KindOpenBraceToken, int(store.Node(node).Pos()), WriteKindPunctuation, store.Node(node))
	format := core.IfElse(p.isEmptyBlock(store.Node(node), node.Statements()) || p.shouldEmitOnSingleLine(store.Node(node)),
		LFSingleLineBlockStatements,
		LFMultiLineBlockStatements)
	p.emitList((*Printer).emitStatement, store.Node(node), node.Statements(), format)
	p.emitTokenEx(ast.KindCloseBraceToken, int(node.Statements().End()), WriteKindPunctuation, store.Node(node), core.IfElse(format&LFMultiLine != 0, tefIndentLeadingComments, tefNone))
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitCaseBlock(node store.CaseBlock) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindOpenBraceToken, int(store.Node(node).Pos()), WriteKindPunctuation, store.Node(node))
	p.emitList((*Printer).emitCaseOrDefaultClauseNode, store.Node(node), node.Clauses(), LFCaseBlockClauses)
	p.emitTokenEx(ast.KindCloseBraceToken, int(node.Clauses().End()), WriteKindPunctuation, store.Node(node), tefIndentLeadingComments)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitImportEqualsDeclaration(node store.ImportEqualsDeclaration) {
	state := p.enterNode(store.Node(node))
	p.emitModifierList(store.Node(node), node.Modifiers(), false /*allowDecorators*/)
	pos := p.emitToken(ast.KindImportKeyword, greatestEnd(int(store.Node(node).Pos()), node.Modifiers()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	if node.IsTypeOnly() {
		p.emitToken(ast.KindTypeKeyword, pos, WriteKindKeyword, store.Node(node))
		p.writeSpace()
	}
	p.emitBindingIdentifier(node.Name().AsIdentifier())
	p.writeSpace()
	p.emitToken(ast.KindEqualsToken, int(node.Name().End()), WriteKindPunctuation, store.Node(node))
	p.writeSpace()
	p.emitModuleReference(node.ModuleReference())
	p.writeTrailingSemicolon()
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitModuleReference(node store.Node) {
	switch node.Kind() {
	case ast.KindIdentifier:
		p.emitIdentifierReference(node.AsIdentifier())
	case ast.KindQualifiedName:
		p.emitQualifiedName(node.AsQualifiedName())
	case ast.KindExternalModuleReference:
		p.emitExternalModuleReference(node.AsExternalModuleReference())
	default:
		panic(fmt.Sprintf("unhandled ModuleReference: %v", node.Kind()))
	}
}

func (p *Printer) emitImportDeclaration(node store.ImportDeclaration) {
	state := p.enterNode(store.Node(node))
	p.emitModifierList(store.Node(node), node.Modifiers(), false /*allowDecorators*/)
	p.emitToken(ast.KindImportKeyword, greatestEnd(int(store.Node(node).Pos()), node.Modifiers()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	if !node.ImportClause().IsNil() {
		p.emitImportClause(node.ImportClause().AsImportClause())
		p.writeSpace()
		p.emitToken(ast.KindFromKeyword, int(node.ImportClause().End()), WriteKindKeyword, store.Node(node))
		p.writeSpace()
	}
	p.emitExpression(node.ModuleSpecifier(), ast.OperatorPrecedenceLowest)
	if !node.Attributes().IsNil() {
		p.writeSpace()
		p.emitImportAttributes(node.Attributes().AsImportAttributes())
	}
	p.writeTrailingSemicolon()
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitImportClause(node store.ImportClause) {
	state := p.enterNode(store.Node(node))
	if node.PhaseModifier() != ast.KindUnknown {
		p.emitToken(node.PhaseModifier(), int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
		p.writeSpace()
	}
	if name := node.Name(); !name.IsNil() {
		p.emitBindingIdentifier(node.Name().AsIdentifier())
		if !node.NamedBindings().IsNil() {
			p.emitToken(ast.KindCommaToken, int(name.End()), WriteKindPunctuation, store.Node(node))
			p.writeSpace()
		}
	}
	p.emitNamedImportBindings(node.NamedBindings())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitNamespaceImport(node store.NamespaceImport) {
	state := p.enterNode(store.Node(node))
	pos := p.emitToken(ast.KindAsteriskToken, int(store.Node(node).Pos()), WriteKindPunctuation, store.Node(node))
	p.writeSpace()
	p.emitToken(ast.KindAsKeyword, pos, WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitBindingIdentifier(node.Name().AsIdentifier())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitNamedImports(node store.NamedImports) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("{")
	p.emitList((*Printer).emitImportSpecifierNode, store.Node(node), node.Elements(), LFNamedImportsOrExportsElements)
	p.writePunctuation("}")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitNamedImportBindings(node store.Node) {
	if node.IsNil() {
		return
	}
	switch node.Kind() {
	case ast.KindNamespaceImport:
		p.emitNamespaceImport(node.AsNamespaceImport())
	case ast.KindNamedImports:
		p.emitNamedImports(node.AsNamedImports())
	default:
		panic(fmt.Sprintf("unhandled NamedImportBindings: %v", node.Kind()))
	}
}

func (p *Printer) emitImportSpecifier(node store.ImportSpecifier) {
	state := p.enterNode(store.Node(node))
	if node.IsTypeOnly() {
		p.writeKeyword("type")
		p.writeSpace()
	}
	if !node.PropertyName().IsNil() {
		p.emitModuleExportName(node.PropertyName())
		p.writeSpace()
		p.emitToken(ast.KindAsKeyword, int(node.PropertyName().End()), WriteKindKeyword, store.Node(node))
		p.writeSpace()
	}
	p.emitBindingIdentifier(node.Name().AsIdentifier())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitImportSpecifierNode(node store.Node) {
	p.emitImportSpecifier(node.AsImportSpecifier())
}

func (p *Printer) emitExportAssignment(node store.ExportAssignment) {
	state := p.enterNode(store.Node(node))
	nextPos := p.emitToken(ast.KindExportKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	if node.IsExportEquals() {
		p.emitToken(ast.KindEqualsToken, nextPos, WriteKindOperator, store.Node(node))
	} else {
		p.emitToken(ast.KindDefaultKeyword, nextPos, WriteKindKeyword, store.Node(node))
	}
	p.writeSpace()
	if node.IsExportEquals() {
		p.emitExpression(node.Expression(), ast.OperatorPrecedenceAssignment)
	} else {
		// parenthesize `class` and `function` expressions so as not to conflict with exported `class` and `function` declarations
		expr := store.GetLeftmostExpression(node.Expression(), false /*stopAtCallExpressions*/)
		if store.IsClassExpression(expr) || store.IsFunctionExpression(expr) {
			p.emitExpression(node.Expression(), ast.OperatorPrecedenceParentheses)
		} else {
			p.emitExpression(node.Expression(), ast.OperatorPrecedenceAssignment)
		}
	}
	p.writeTrailingSemicolon()
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitExportDeclaration(node store.ExportDeclaration) {
	state := p.enterNode(store.Node(node))
	p.emitModifierList(store.Node(node), node.Modifiers(), false /*allowDecorators*/)
	pos := p.emitToken(ast.KindExportKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	if node.IsTypeOnly() {
		pos = p.emitToken(ast.KindTypeKeyword, pos, WriteKindKeyword, store.Node(node))
		p.writeSpace()
	}
	if !node.ExportClause().IsNil() {
		p.emitNamedExportBindings(node.ExportClause())
	} else {
		pos = p.emitToken(ast.KindAsteriskToken, pos, WriteKindPunctuation, store.Node(node))
	}
	if !node.ModuleSpecifier().IsNil() {
		p.writeSpace()
		p.emitToken(ast.KindFromKeyword, greatestEnd(pos, node.ExportClause()), WriteKindKeyword, store.Node(node))
		p.writeSpace()
		p.emitExpression(node.ModuleSpecifier(), ast.OperatorPrecedenceLowest)
	}
	if !node.Attributes().IsNil() {
		p.writeSpace()
		p.emitImportAttributes(node.Attributes().AsImportAttributes())
	}
	p.writeTrailingSemicolon()
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitImportAttributes(node store.ImportAttributes) {
	state := p.enterNode(store.Node(node))
	p.emitToken(node.Token(), int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitList((*Printer).emitImportAttributeNode, store.Node(node), node.Attributes(), LFImportAttributes)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitImportAttribute(node store.ImportAttribute) {
	state := p.enterNode(store.Node(node))
	p.emitImportAttributeName(node.Name())
	p.writePunctuation(":")
	p.writeSpace()
	value := node.Value()
	if p.emitContext.EmitFlags(node.Value())&EFNoLeadingComments == 0 {
		commentRange := p.emitContext.CommentRange(value)
		p.emitTrailingComments(commentRange.Pos(), commentSeparatorAfter)
	}
	p.emitExpression(value, ast.OperatorPrecedenceDisallowComma)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitImportAttributeNode(node store.Node) {
	p.emitImportAttribute(node.AsImportAttribute())
}

func (p *Printer) emitNamespaceExportDeclaration(node store.NamespaceExportDeclaration) {
	state := p.enterNode(store.Node(node))
	pos := p.emitToken(ast.KindExportKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	pos = p.emitToken(ast.KindAsKeyword, pos, WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitToken(ast.KindNamespaceKeyword, pos, WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitBindingIdentifier(node.Name().AsIdentifier())
	p.writeTrailingSemicolon()
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitNamespaceExport(node store.NamespaceExport) {
	state := p.enterNode(store.Node(node))
	pos := p.emitToken(ast.KindAsteriskToken, int(store.Node(node).Pos()), WriteKindPunctuation, store.Node(node))
	p.writeSpace()
	p.emitToken(ast.KindAsKeyword, pos, WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitModuleExportName(node.Name())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitNamedExports(node store.NamedExports) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("{")
	p.emitList((*Printer).emitExportSpecifierNode, store.Node(node), node.Elements(), LFNamedImportsOrExportsElements)
	p.writePunctuation("}")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitNamedExportBindings(node store.Node) {
	switch node.Kind() {
	case ast.KindNamespaceExport:
		p.emitNamespaceExport(node.AsNamespaceExport())
	case ast.KindNamedExports:
		p.emitNamedExports(node.AsNamedExports())
	default:
		panic(fmt.Sprintf("unhandled NamedExportBindings: %v", node.Kind()))
	}
}

func (p *Printer) emitExportSpecifier(node store.ExportSpecifier) {
	state := p.enterNode(store.Node(node))
	if node.IsTypeOnly() {
		p.writeKeyword("type")
		p.writeSpace()
	}
	if !node.PropertyName().IsNil() {
		p.emitModuleExportName(node.PropertyName())
		p.writeSpace()
		p.emitToken(ast.KindAsKeyword, int(node.PropertyName().End()), WriteKindKeyword, store.Node(node))
		p.writeSpace()
	}
	p.emitModuleExportName(node.Name())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitExportSpecifierNode(node store.Node) {
	p.emitExportSpecifier(node.AsExportSpecifier())
}

func (p *Printer) emitEmbeddedStatement(parentNode store.Node, node store.Node) {
	if store.IsBlock(node) ||
		p.shouldEmitOnSingleLine(parentNode) ||
		p.Options.PreserveSourceNewlines && p.getLeadingLineTerminatorCount(parentNode, node, LFNone) == 0 {
		p.writeSpace()
		p.emitStatement(node)
	} else {
		p.writeLine()
		p.increaseIndent()
		if node.Kind() == ast.KindEmptyStatement {
			p.emitEmptyStatement(node, true /*isEmbeddedStatement*/)
		} else {
			p.emitStatement(node)
		}
		p.decreaseIndent()
	}
}

func (p *Printer) emitStatement(node store.Node) {
	if snippetElement := p.emitContext.SnippetElement(node); snippetElement != nil {
		p.emitSnippetNode(node, snippetElement)
		return
	}

	switch node.Kind() {
	// Statements
	case ast.KindBlock:
		p.emitBlock(node.AsBlock())
	case ast.KindEmptyStatement:
		p.emitEmptyStatement(node, false /*isEmbeddedStatement*/)
	case ast.KindVariableStatement:
		p.emitVariableStatement(node.AsVariableStatement())
	case ast.KindExpressionStatement:
		p.emitExpressionStatement(node.AsExpressionStatement())
	case ast.KindIfStatement:
		p.emitIfStatement(node.AsIfStatement())
	case ast.KindDoStatement:
		p.emitDoStatement(node.AsDoStatement())
	case ast.KindWhileStatement:
		p.emitWhileStatement(node.AsWhileStatement())
	case ast.KindForStatement:
		p.emitForStatement(node.AsForStatement())
	case ast.KindForInStatement:
		p.emitForInStatement(node.AsForInOrOfStatement())
	case ast.KindForOfStatement:
		p.emitForOfStatement(node.AsForInOrOfStatement())
	case ast.KindContinueStatement:
		p.emitContinueStatement(node.AsContinueStatement())
	case ast.KindBreakStatement:
		p.emitBreakStatement(node.AsBreakStatement())
	case ast.KindReturnStatement:
		p.emitReturnStatement(node.AsReturnStatement())
	case ast.KindWithStatement:
		p.emitWithStatement(node.AsWithStatement())
	case ast.KindSwitchStatement:
		p.emitSwitchStatement(node.AsSwitchStatement())
	case ast.KindLabeledStatement:
		p.emitLabeledStatement(node.AsLabeledStatement())
	case ast.KindThrowStatement:
		p.emitThrowStatement(node.AsThrowStatement())
	case ast.KindTryStatement:
		p.emitTryStatement(node.AsTryStatement())
	case ast.KindDebuggerStatement:
		p.emitDebuggerStatement(node)
	case ast.KindNotEmittedStatement:
		p.emitNotEmittedStatement(node)

	// Declaration Statements
	case ast.KindFunctionDeclaration:
		p.emitFunctionDeclaration(node.AsFunctionDeclaration())
	case ast.KindClassDeclaration:
		p.emitClassDeclaration(node.AsClassDeclaration())
	case ast.KindInterfaceDeclaration:
		p.emitInterfaceDeclaration(node.AsInterfaceDeclaration())
	case ast.KindTypeAliasDeclaration, ast.KindJSTypeAliasDeclaration:
		p.emitTypeAliasDeclaration(node.AsTypeAliasDeclaration())
	case ast.KindEnumDeclaration:
		p.emitEnumDeclaration(node.AsEnumDeclaration())
	case ast.KindModuleDeclaration:
		p.emitModuleDeclaration(node.AsModuleDeclaration())
	case ast.KindMissingDeclaration:
		break

	// Import/Export Statements
	case ast.KindNamespaceExportDeclaration:
		p.emitNamespaceExportDeclaration(node.AsNamespaceExportDeclaration())
	case ast.KindImportEqualsDeclaration:
		p.emitImportEqualsDeclaration(node.AsImportEqualsDeclaration())
	case ast.KindImportDeclaration:
		p.emitImportDeclaration(node.AsImportDeclaration())
	case ast.KindExportAssignment:
		p.emitExportAssignment(node.AsExportAssignment())
	case ast.KindExportDeclaration:
		p.emitExportDeclaration(node.AsExportDeclaration())

	default:
		panic(fmt.Sprintf("unhandled statement: %v", node.Kind()))
	}
}

func (p *Printer) emitExternalModuleReference(node store.ExternalModuleReference) {
	state := p.enterNode(store.Node(node))
	p.writeKeyword("require")
	p.writePunctuation("(")
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceDisallowComma)
	p.writePunctuation(")")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJsxElement(node store.JsxElement) {
	state := p.enterNode(store.Node(node))
	p.emitJsxOpeningElement(node.OpeningElement().AsJsxOpeningElement())
	p.emitList((*Printer).emitJsxChild, store.Node(node), node.Children(), LFJsxElementOrFragmentChildren)
	p.emitJsxClosingElement(node.ClosingElement().AsJsxClosingElement())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJsxSelfClosingElement(node store.JsxSelfClosingElement) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("<")
	p.emitJsxTagName(node.TagName())
	p.emitTypeArguments(store.Node(node), node.TypeArguments())
	p.writeSpace()
	p.emitJsxAttributes(node.Attributes().AsJsxAttributes())
	p.writePunctuation("/>")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJsxFragment(node store.JsxFragment) {
	state := p.enterNode(store.Node(node))
	p.emitJsxOpeningFragment(node.OpeningFragment())
	p.emitList((*Printer).emitJsxChild, store.Node(node), node.Children(), LFJsxElementOrFragmentChildren)
	p.emitJsxClosingFragment(node.ClosingFragment())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJsxOpeningElement(node store.JsxOpeningElement) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("<")
	indented := p.writeLineSeparatorsAndIndentBefore(node.TagName(), store.Node(node))
	p.emitJsxTagName(node.TagName())
	p.emitTypeArguments(store.Node(node), node.TypeArguments())
	if node.Attributes().Properties().Len() > 0 {
		p.writeSpace()
	}
	p.emitJsxAttributes(node.Attributes().AsJsxAttributes())
	p.writeLineSeparatorsAfter(node.Attributes(), store.Node(node))
	p.decreaseIndentIf(indented)
	p.writePunctuation(">")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJsxClosingElement(node store.JsxClosingElement) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("</")
	p.emitJsxTagName(node.TagName())
	p.writePunctuation(">")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJsxOpeningFragment(node store.Node) {
	state := p.enterNode(node)
	p.writePunctuation("<")
	p.writePunctuation(">")
	p.exitNode(node, state)
}

func (p *Printer) emitJsxClosingFragment(node store.Node) {
	state := p.enterNode(node)
	p.writePunctuation("</")
	p.writePunctuation(">")
	p.exitNode(node, state)
}

func (p *Printer) emitJsxText(node store.JsxText) {
	state := p.enterNode(store.Node(node))
	// TODO(rbuckton): Should this be using `getLiteralTextOfNode` instead?
	p.writeLiteral(node.Text())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJsxAttributes(node store.JsxAttributes) {
	state := p.enterNode(store.Node(node))
	p.emitList((*Printer).emitJsxAttributeLike, store.Node(node), node.Properties(), LFJsxElementAttributes)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJsxAttribute(node store.JsxAttribute) {
	state := p.enterNode(store.Node(node))
	p.emitJsxAttributeName(node.Name())
	if !node.Initializer().IsNil() {
		p.writePunctuation("=")
		p.emitJsxAttributeValue(node.Initializer())
	}
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJsxSpreadAttribute(node store.JsxSpreadAttribute) {
	state := p.enterNode(store.Node(node))
	p.writePunctuation("{...")
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceLowest)
	p.writePunctuation("}")
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJsxAttributeLike(node store.Node) {
	switch node.Kind() {
	case ast.KindJsxAttribute:
		p.emitJsxAttribute(node.AsJsxAttribute())
	case ast.KindJsxSpreadAttribute:
		p.emitJsxSpreadAttribute(node.AsJsxSpreadAttribute())
	default:
		panic(fmt.Sprintf("unhandled JsxAttributeLike: %v", node.Kind()))
	}
}

func (p *Printer) emitJsxExpression(node store.JsxExpression) {
	state := p.enterNode(store.Node(node))
	if !node.Expression().IsNil() || !p.commentsDisabled && !store.NodeIsSynthesized(store.Node(node)) && p.hasCommentsAtPosition(int(store.Node(node).Pos())) { // preserve empty expressions if they contain comments!
		indented := p.currentSourceFile != nil && !store.NodeIsSynthesized(store.Node(node)) && GetLinesBetweenPositions(p.currentSourceFile, int(store.Node(node).Pos()), int(store.Node(node).End())) != 0
		p.increaseIndentIf(indented)
		end := p.emitToken(ast.KindOpenBraceToken, int(store.Node(node).Pos()), WriteKindPunctuation, store.Node(node))
		p.emitTokenNode(node.DotDotDotToken())
		if !node.Expression().IsNil() {
			p.emitExpression(node.Expression(), ast.OperatorPrecedenceDisallowComma)
		}
		p.emitToken(ast.KindCloseBraceToken, greatestEnd(end, node.Expression(), node.DotDotDotToken()), WriteKindPunctuation, store.Node(node))
		p.decreaseIndentIf(indented)
	}
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJsxNamespacedName(node store.JsxNamespacedName) {
	state := p.enterNode(store.Node(node))
	p.emitIdentifierName(node.Namespace().AsIdentifier())
	p.writePunctuation(":")
	p.emitIdentifierName(node.Name().AsIdentifier())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitJsxChild(node store.Node) {
	switch node.Kind() {
	case ast.KindJsxText:
		p.emitJsxText(node.AsJsxText())
	case ast.KindJsxExpression:
		p.emitJsxExpression(node.AsJsxExpression())
	case ast.KindJsxElement:
		p.emitJsxElement(node.AsJsxElement())
	case ast.KindJsxSelfClosingElement:
		p.emitJsxSelfClosingElement(node.AsJsxSelfClosingElement())
	case ast.KindJsxFragment:
		p.emitJsxFragment(node.AsJsxFragment())
	default:
		panic(fmt.Sprintf("unhandled JsxChild: %v", node.Kind()))
	}
}

func (p *Printer) emitJsxTagName(node store.Node) {
	switch node.Kind() {
	case ast.KindIdentifier:
		p.emitIdentifierReference(node.AsIdentifier())
	case ast.KindThisKeyword:
		p.emitKeywordExpression(node)
	case ast.KindJsxNamespacedName:
		p.emitJsxNamespacedName(node.AsJsxNamespacedName())
	case ast.KindPropertyAccessExpression:
		p.emitPropertyAccessExpression(node.AsPropertyAccessExpression())
	default:
		panic(fmt.Sprintf("unhandled JsxTagName: %v", node.Kind()))
	}
}

func (p *Printer) emitJsxAttributeName(node store.Node) {
	switch node.Kind() {
	case ast.KindIdentifier:
		p.emitIdentifierName(node.AsIdentifier())
	case ast.KindJsxNamespacedName:
		p.emitJsxNamespacedName(node.AsJsxNamespacedName())
	default:
		panic(fmt.Sprintf("unhandled JsxAttributeName: %v", node.Kind()))
	}
}

func (p *Printer) emitJsxAttributeValue(node store.Node) {
	switch node.Kind() {
	case ast.KindStringLiteral:
		p.emitStringLiteral(node.AsStringLiteral())
	case ast.KindJsxExpression:
		p.emitJsxExpression(node.AsJsxExpression())
	case ast.KindJsxElement:
		p.emitJsxElement(node.AsJsxElement())
	case ast.KindJsxSelfClosingElement:
		p.emitJsxSelfClosingElement(node.AsJsxSelfClosingElement())
	case ast.KindJsxFragment:
		p.emitJsxFragment(node.AsJsxFragment())
	default:
		p.emitExpression(node, ast.OperatorPrecedenceLowest)
	}
}

func (p *Printer) emitCaseOrDefaultClauseStatements(node store.CaseOrDefaultClause, colonPos int) {
	emitAsSingleStatement := node.Statements().Len() == 1 &&
		// treat synthesized nodes as located on the same line for emit purposes
		(p.currentSourceFile == nil ||
			store.NodeIsSynthesized(store.Node(node)) ||
			store.NodeIsSynthesized(node.Statements().At(0)) ||
			RangeStartPositionsAreOnSameLine(store.Node(node).Loc(), node.Statements().At(0).Loc(), p.currentSourceFile))

	format := LFCaseOrDefaultClauseStatements
	if emitAsSingleStatement {
		// When emitting as a single statement, use writeToken (no comments) for the colon
		// to avoid duplicating trailing comments that will be picked up by the statement list.
		p.writeTokenText(ast.KindColonToken, WriteKindPunctuation, colonPos)
		p.writeSpace()
		format &^= LFMultiLine | LFIndented
	} else {
		p.emitToken(ast.KindColonToken, colonPos, WriteKindPunctuation, store.Node(node))
	}

	p.emitList((*Printer).emitStatement, store.Node(node), node.Statements(), format)
}

func (p *Printer) emitCaseClause(node store.CaseOrDefaultClause) {
	state := p.enterNode(store.Node(node))
	p.emitToken(ast.KindCaseKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitExpression(node.Expression(), ast.OperatorPrecedenceLowest)
	p.emitCaseOrDefaultClauseStatements(node, int(node.Expression().End()))
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitDefaultClause(node store.CaseOrDefaultClause) {
	state := p.enterNode(store.Node(node))
	pos := p.emitToken(ast.KindDefaultKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.emitCaseOrDefaultClauseStatements(node, pos)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitCaseOrDefaultClauseNode(node store.Node) {
	switch node.Kind() {
	case ast.KindCaseClause:
		p.emitCaseClause(node.AsCaseOrDefaultClause())
	case ast.KindDefaultClause:
		p.emitDefaultClause(node.AsCaseOrDefaultClause())
	default:
		panic(fmt.Sprintf("unhandled CaseOrDefaultClause: %v", node.Kind()))
	}
}

func (p *Printer) emitHeritageClause(node store.HeritageClause) {
	state := p.enterNode(store.Node(node))
	p.writeSpace()
	p.emitToken(node.Token(), int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()
	p.emitList((*Printer).emitHeritageClauseElement, store.Node(node), node.Types(), LFHeritageClauseTypes)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitHeritageClauseElement(node store.Node) {
	switch node.Kind() {
	case ast.KindExpressionWithTypeArguments:
		p.emitExpressionWithTypeArguments(node.AsExpressionWithTypeArguments())
	case ast.KindTypeReference:
		p.emitTypeReference(node.AsTypeReferenceNode())
	default:
		panic(fmt.Sprintf("unhandled HeritageClauseElement: %v", node.Kind()))
	}
}

func (p *Printer) emitHeritageClauseNode(node store.Node) {
	p.emitHeritageClause(node.AsHeritageClause())
}

func (p *Printer) emitCatchClause(node store.CatchClause) {
	state := p.enterNode(store.Node(node))
	openParenPos := p.emitToken(ast.KindCatchKeyword, int(store.Node(node).Pos()), WriteKindKeyword, store.Node(node))
	p.writeSpace()

	if !node.VariableDeclaration().IsNil() {
		p.emitToken(ast.KindOpenParenToken, openParenPos, WriteKindPunctuation, store.Node(node))
		p.emitVariableDeclaration(node.VariableDeclaration().AsVariableDeclaration())
		p.emitToken(ast.KindCloseParenToken, int(node.VariableDeclaration().End()), WriteKindPunctuation, store.Node(node))
		p.writeSpace()
	}

	p.emitBlock(node.Block().AsBlock())
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitPropertyAssignment(node store.PropertyAssignment) {
	state := p.enterNode(store.Node(node))
	p.emitPropertyName(node.Name())
	p.writePunctuation(":")
	p.writeSpace()
	// This is to ensure that we emit comment in the following case:
	//      For example:
	//          obj = {
	//              id: /*comment1*/ ()=>void
	//          }
	// "comment1" is not considered to be leading comment for node.initializer
	// but rather a trailing comment on the previous node.
	initializer := node.Initializer()
	if p.emitContext.EmitFlags(initializer)&EFNoLeadingComments == 0 {
		commentRange := p.emitContext.CommentRange(initializer)
		p.emitTrailingComments(commentRange.Pos(), commentSeparatorAfter)
	}
	p.emitExpression(initializer, ast.OperatorPrecedenceDisallowComma)
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitShorthandPropertyAssignment(node store.ShorthandPropertyAssignment) {
	state := p.enterNode(store.Node(node))
	p.emitPropertyName(node.Name())
	if !node.ObjectAssignmentInitializer().IsNil() {
		p.writeSpace()
		p.writePunctuation("=")
		p.writeSpace()
		p.emitExpression(node.ObjectAssignmentInitializer(), ast.OperatorPrecedenceDisallowComma)
	}
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitSpreadAssignment(node store.SpreadAssignment) {
	state := p.enterNode(store.Node(node))
	if !node.Expression().IsNil() {
		p.emitToken(ast.KindDotDotDotToken, int(store.Node(node).Pos()), WriteKindPunctuation, store.Node(node))
		p.emitExpression(node.Expression(), ast.OperatorPrecedenceDisallowComma)
	}
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitEnumMember(node store.EnumMember) {
	state := p.enterNode(store.Node(node))
	p.emitPropertyName(node.Name())
	p.emitInitializer(node.Initializer(), int(node.Name().End()), store.Node(node))
	p.exitNode(store.Node(node), state)
}

func (p *Printer) emitEnumMemberNode(node store.Node) {
	p.emitEnumMember(node.AsEnumMember())
}

func (p *Printer) emitJSDocNode(node store.Node) {
	// !!!
	panic("not implemented")
}

func (p *Printer) emitShebangIfNeeded(node *store.File) {
	if store.NodeIsSynthesized(node.Root()) {
		return
	}
	shebang := scanner.GetShebang(node.Text())
	if shebang != "" {
		p.writeComment(shebang)
		p.writeLine()
	}
}

func (p *Printer) emitPrologueDirectives(statements store.List) int {
	for i := range statements.Len() {
		statement := statements.At(i)
		if store.IsPrologueDirective(statement) {
			p.writeLine()
			p.emitStatement(statement)
		} else {
			return i
		}
	}
	return statements.Len()
}

func (p *Printer) emitHelpers(node store.Node) bool {
	helpersEmitted := false
	sourceFile := p.currentSourceFile
	shouldSkip := p.Options.NoEmitHelpers || (sourceFile != nil && p.emitContext.HasRecordedExternalHelpers(sourceFile))
	helpers := slices.Clone(p.emitContext.GetEmitHelpers(node))
	if len(helpers) > 0 {
		slices.SortStableFunc(helpers, compareEmitHelpers)
		for _, helper := range helpers {
			if !helper.Scoped {
				// Skip the helper if it can be skipped and the noEmitHelpers compiler
				// option is set, or if it can be imported and the importHelpers compiler
				// option is set.
				if shouldSkip {
					continue
				}
			}
			if helper.TextCallback != nil {
				p.writeLines(helper.TextCallback(p.makeFileLevelOptimisticUniqueName))
			} else {
				p.writeLines(helper.Text)
			}
			helpersEmitted = true
		}
	}

	return helpersEmitted
}

func (p *Printer) emitSourceFile(node *store.File) {
	savedCurrentSourceFile := p.currentSourceFile
	savedCommentsDisabled := p.commentsDisabled
	p.currentSourceFile = node

	p.writeLine()

	p.pushNameGenerationScope(node.Root())
	p.generateAllNames(node.Statements())

	index := 0
	var state *commentState
	if node.ScriptKind != core.ScriptKindJSON {
		p.emitShebangIfNeeded(node)
		index = p.emitPrologueDirectives(node.Statements())
		if !p.writer.IsAtStartOfLine() {
			p.writeLine()
		}
		state = p.emitDetachedCommentsBeforeStatementList(node.Root(), node.Statements().Loc())
		p.emitHelpers(node.Root())
		if node.IsDeclarationFile {
			p.emitTripleSlashDirectives(node)
		}
	} else {
		state = p.emitDetachedCommentsBeforeStatementList(node.Root(), node.Statements().Loc())
	}

	// !!! Emit triple-slash directives
	p.emitListRange(
		(*Printer).emitStatement,
		node.Root(),
		node.Statements(),
		LFMultiLine,
		index,
		-1, /*count*/
	)
	p.popNameGenerationScope(node.Root())
	p.emitDetachedCommentsAfterStatementList(node.Root(), node.Statements().Loc(), state)
	p.currentSourceFile = savedCurrentSourceFile
	p.commentsDisabled = savedCommentsDisabled
}

func (p *Printer) emitTripleSlashDirectives(node *store.File) {
	p.emitDirective("path", node.ReferencedFiles)
	p.emitDirective("types", node.TypeReferenceDirectives)
	p.emitDirective("lib", node.LibReferenceDirectives)
}

func (p *Printer) emitDirective(kind string, refs []*ast.FileReference) {
	for _, ref := range refs {
		var resolutionMode string
		if ref.ResolutionMode != core.ResolutionModeNone {
			resolutionMode = fmt.Sprintf(`resolution-mode="%s" `, core.IfElse(ref.ResolutionMode == core.ResolutionModeESM, "import", "require"))
		}
		p.writeComment(fmt.Sprintf("/// <reference %s=\"%s\" %s%s/>", kind, ref.FileName, resolutionMode, core.IfElse(ref.Preserve, `preserve="true" `, "")))
		p.writeLine()
	}
}

func (p *Printer) emitList(emit func(p *Printer, node store.Node), parentNode store.Node, children store.List, format ListFormat) {
	if p.shouldEmitOnMultipleLines(parentNode) {
		format |= LFPreferNewLine | LFIndented
	}

	p.emitListRange(emit, parentNode, children, format, -1 /*start*/, -1 /*count*/)
}

func (p *Printer) emitListRange(emit func(p *Printer, node store.Node), parentNode store.Node, children store.List, format ListFormat, start int, count int) {
	isNil := children.IsNil()

	length := 0
	if !isNil {
		length = children.Len()
	}

	if start < 0 {
		start = 0
	}

	if count < 0 {
		count = length - start
	}

	if isNil && format&LFOptionalIfNil != 0 {
		return
	}

	isEmpty := isNil || start >= length || count <= 0
	if isEmpty && format&LFOptionalIfEmpty != 0 {
		if p.OnBeforeEmitNodeList != nil {
			p.OnBeforeEmitNodeList(children)
		}
		if p.OnAfterEmitNodeList != nil {
			p.OnAfterEmitNodeList(children)
		}
		return
	}

	if format&LFBracketsMask != 0 {
		p.writePunctuation(getOpeningBracket(format))
		if isEmpty && !isNil {
			p.emitTrailingComments(int(children.Pos()), commentSeparatorBefore) // Emit comments within empty lists
		}
	}

	if p.OnBeforeEmitNodeList != nil {
		p.OnBeforeEmitNodeList(children)
	}

	if isEmpty {
		// Write a line terminator if the parent node was multi-line
		if format&LFMultiLine != 0 && !(p.Options.PreserveSourceNewlines && (parentNode.IsNil() || p.currentSourceFile != nil && RangeIsOnSingleLine(parentNode.Loc(), p.currentSourceFile))) {
			p.writeLine()
		} else if format&LFSpaceBetweenBraces != 0 && format&LFNoSpaceIfEmpty == 0 {
			p.writeSpace()
		}
	} else {
		end := min(start+count, length)

		p.emitListItems(emit, parentNode, children.Nodes()[start:end], format, p.hasTrailingComma(parentNode, children), children.Loc())
	}

	if p.OnAfterEmitNodeList != nil {
		p.OnAfterEmitNodeList(children)
	}

	if format&LFBracketsMask != 0 {
		if isEmpty && !isNil {
			p.emitLeadingComments(int(children.End()), false /*elided*/) // Emit comments within empty lists
		}
		p.writePunctuation(getClosingBracket(format))
	}
}

func (p *Printer) hasTrailingComma(parentNode store.Node, children store.List) bool {
	// NodeList.HasTrailingComma() is unreliable on transformed nodes as some nodes may have been removed. In the event
	// we believe we may need to emit a trailing comma, we must first look to the respective node list on the original
	// node first.
	if !children.HasTrailingComma() {
		return false
	}

	originalParent := p.emitContext.MostOriginal(parentNode)
	if store.SameNode(originalParent, parentNode) {
		// if this node is the original node, we can trust the result
		return true
	}

	if originalParent.Kind() != parentNode.Kind() {
		// if the original node is some other kind of node, we cannot correlate the list
		return false
	}

	// find the respective node list on the original parent
	originalList := children
	switch originalParent.Kind() {
	case ast.KindObjectLiteralExpression:
		originalList = originalParent.PropertyList()
	case ast.KindArrayLiteralExpression:
		originalList = originalParent.ElementList()
	case ast.KindCallExpression, ast.KindNewExpression:
		switch {
		case store.SameList(children, parentNode.TypeArgumentList()):
			originalList = originalParent.TypeArgumentList()
		case store.SameList(children, parentNode.ArgumentList()):
			originalList = originalParent.ArgumentList()
		}
	case ast.KindConstructor,
		ast.KindMethodDeclaration,
		ast.KindGetAccessor,
		ast.KindSetAccessor,
		ast.KindFunctionDeclaration,
		ast.KindFunctionExpression,
		ast.KindArrowFunction,
		ast.KindFunctionType,
		ast.KindConstructorType,
		ast.KindCallSignature,
		ast.KindConstructSignature:
		switch {
		case store.SameList(children, parentNode.TypeParameterList()):
			originalList = originalParent.TypeParameterList()
		case store.SameList(children, parentNode.ParameterList()):
			originalList = originalParent.ParameterList()
		}
	case ast.KindClassDeclaration, ast.KindClassExpression, ast.KindInterfaceDeclaration, ast.KindTypeAliasDeclaration, ast.KindJSTypeAliasDeclaration:
		switch {
		case store.SameList(children, parentNode.TypeParameterList()):
			originalList = originalParent.TypeParameterList()
		}
	case ast.KindObjectBindingPattern, ast.KindArrayBindingPattern:
		switch {
		case store.SameList(children, parentNode.ElementList()):
			originalList = originalParent.ElementList()
		}
	case ast.KindNamedImports, ast.KindNamedExports:
		originalList = originalParent.ElementList()
	case ast.KindImportAttributes:
		originalList = originalParent.AsImportAttributes().Attributes()
	}

	// if we have the original list, we can use it's result.
	if !originalList.IsNil() {
		return originalList.HasTrailingComma()
	}

	return false
}

func (p *Printer) writeDelimiter(format ListFormat) {
	switch format & LFDelimitersMask {
	case LFNone:
		break
	case LFCommaDelimited:
		p.writePunctuation(",")
	case LFBarDelimited:
		p.writeSpace()
		p.writePunctuation("|")
	case LFAsteriskDelimited:
		p.writeSpace()
		p.writePunctuation("*")
		p.writeSpace()
	case LFAmpersandDelimited:
		p.writeSpace()
		p.writePunctuation("&")
	}
}

func (p *Printer) emitListItems(
	emit func(p *Printer, node store.Node),
	parentNode store.Node,
	children []store.Node,
	format ListFormat,
	hasTrailingComma bool,
	childrenTextRange core.TextRange,
) {
	// Write the opening line terminator or leading whitespace.
	mayEmitInterveningComments := format&LFNoInterveningComments == 0
	shouldEmitInterveningComments := mayEmitInterveningComments

	leadingLineTerminatorCount := 0
	if len(children) > 0 {
		leadingLineTerminatorCount = p.getLeadingLineTerminatorCount(parentNode, children[0], format)
	}
	if leadingLineTerminatorCount > 0 {
		for range leadingLineTerminatorCount {
			p.writeLine()
		}
		shouldEmitInterveningComments = false
	} else if format&LFSpaceBetweenBraces != 0 {
		p.writeSpace()
	}

	// Increase the indent, if requested.
	if format&LFIndented != 0 {
		p.increaseIndent()
	}

	parentEnd := greatestEnd(-1, parentNode)

	// Emit each child.
	var previousSibling store.Node
	shouldDecreaseIndentAfterEmit := false
	for _, child := range children {
		// Write the delimiter if this is not the first node.
		if format&LFAsteriskDelimited != 0 {
			// always write JSDoc in the format "\n *"
			p.writeLine()
			p.writeDelimiter(format)
		} else if !previousSibling.IsNil() {
			// i.e
			//      function commentedParameters(
			//          /* Parameter a */
			//          a
			//          /* End of parameter a */ -> this comment isn't considered to be trailing comment of parameter "a" due to newline
			//          ,
			if format&LFDelimitersMask != 0 && int(previousSibling.End()) != parentEnd {
				if !p.commentsDisabled && p.shouldEmitTrailingComments(previousSibling) {
					p.emitLeadingComments(int(previousSibling.End()), false /*elided*/)
				}
			}

			p.writeDelimiter(format)

			// Write either a line terminator or whitespace to separate the elements.
			separatingLineTerminatorCount := p.getSeparatingLineTerminatorCount(previousSibling, child, format)
			if separatingLineTerminatorCount > 0 {
				// If a synthesized node in a single-line list starts on a new
				// line, we should increase the indent.
				if format&(LFLinesMask|LFIndented) == LFSingleLine {
					p.increaseIndent()
					shouldDecreaseIndentAfterEmit = true
				}

				if shouldEmitInterveningComments && format&LFDelimitersMask != 0 && !ast.PositionIsSynthesized(int(child.Pos())) && p.shouldEmitLeadingComments(child) {
					commentRange := p.emitContext.CommentRange(child)
					p.emitTrailingCommentsOfPosition(commentRange.Pos(), format&LFSpaceBetweenSiblings != 0, true /*forceNoNewline*/)
				}

				for range separatingLineTerminatorCount {
					p.writeLine()
				}

				shouldEmitInterveningComments = false
			} else if format&LFSpaceBetweenSiblings != 0 {
				p.writeSpace()
			}
		}

		// Emit this child.
		if shouldEmitInterveningComments && p.shouldEmitLeadingComments(child) {
			commentRange := p.emitContext.CommentRange(child)
			p.emitTrailingCommentsOfPosition(commentRange.Pos(), false /*prefixSpace*/, false /*forceNoNewline*/)
		} else {
			shouldEmitInterveningComments = mayEmitInterveningComments
		}

		p.nextListElementPos = int(child.Pos())
		emit(p, child)

		if shouldDecreaseIndentAfterEmit {
			p.decreaseIndent()
			shouldDecreaseIndentAfterEmit = false
		}

		previousSibling = child
	}

	// Write a trailing comma, if requested.
	skipTrailingComments := p.commentsDisabled || !p.shouldEmitTrailingComments(previousSibling)
	emitTrailingComma := hasTrailingComma && format&LFAllowTrailingComma != 0 && format&LFCommaDelimited != 0
	if emitTrailingComma {
		if !previousSibling.IsNil() && !skipTrailingComments {
			p.emitToken(ast.KindCommaToken, int(previousSibling.End()), WriteKindPunctuation, previousSibling)
		} else {
			p.writePunctuation(",")
		}
	}

	// Emit any trailing comment of the last element in the list
	// i.e
	//       var array = [...
	//          2
	//          /* end of element 2 */
	//       ];
	if !previousSibling.IsNil() && parentEnd != int(previousSibling.End()) && format&LFDelimitersMask != 0 && !skipTrailingComments {
		var commentsPos int
		if emitTrailingComma && childrenTextRange.End() > 0 {
			commentsPos = childrenTextRange.End()
		} else {
			commentsPos = int(previousSibling.End())
		}
		p.emitLeadingComments(commentsPos, false /*elided*/)
	}

	// Decrease the indent, if requested.
	if format&LFIndented != 0 {
		p.decreaseIndent()
	}

	// Write the closing line terminator or closing whitespace.
	closingLineTerminatorCount := p.getClosingLineTerminatorCount(parentNode, core.LastOrNil(children), format, childrenTextRange)
	if closingLineTerminatorCount > 0 {
		for range closingLineTerminatorCount {
			p.writeLine()
		}
	} else if format&(LFSpaceAfterList|LFSpaceBetweenBraces) != 0 {
		p.writeSpace()
	}
}

func (p *Printer) setSourceFile(sourceFile *store.File) {
	p.currentSourceFile = sourceFile
	p.uniqueHelperNames = nil
	p.externalHelpersModuleName = store.Node{}
	if sourceFile != nil {
		if p.emitContext.EmitFlags(p.emitContext.MostOriginal(sourceFile.Root()))&EFExternalHelpers != 0 {
			p.uniqueHelperNames = make(map[string]store.Node)
		}
		p.externalHelpersModuleName = p.emitContext.GetExternalHelpersModuleName(sourceFile)
		p.setSourceMapSource(sourceFile)
	}

	// !!!
}

func (p *Printer) Write(node store.Node, sourceFile *store.File, writer EmitTextWriter, sourceMapGenerator *sourcemap.Generator) {
	savedCurrentSourceFile := p.currentSourceFile
	savedWriter := p.writer
	savedUniqueHelperNames := p.uniqueHelperNames
	savedSourceMapsDisabled := p.sourceMapsDisabled
	savedSourceMapGenerator := p.sourceMapGenerator
	savedSourceMapSource := p.sourceMapSource
	savedSourceMapSourceIndex := p.sourceMapSourceIndex
	savedSourceMapLineCharCache := p.sourceMapLineCharCache

	p.sourceMapsDisabled = sourceMapGenerator == nil
	p.sourceMapGenerator = sourceMapGenerator
	p.sourceMapSource = nil
	p.sourceMapSourceIndex = -1
	p.sourceMapLineCharCache = nil

	p.setSourceFile(sourceFile)
	if p.Options.OmitTrailingSemicolon {
		writer = getTrailingSemicolonDeferringWriter(writer)
	}
	p.writer = writer
	p.writer.Clear()
	if sourceFile != nil {
		if grower, ok := p.writer.(interface{ Grow(n int) }); ok {
			grower.Grow(len(sourceFile.Text()))
		}
	}

	switch node.Kind() {
	// Pseudo-literals
	case ast.KindTemplateHead:
		p.emitTemplateHead(node.AsTemplateHead())
	case ast.KindTemplateMiddle:
		p.emitTemplateMiddle(node.AsTemplateMiddle())
	case ast.KindTemplateTail:
		p.emitTemplateTail(node.AsTemplateTail())

	// Identifiers
	case ast.KindIdentifier:
		p.emitIdentifierName(node.AsIdentifier())

	// PrivateIdentifiers
	case ast.KindPrivateIdentifier:
		p.emitPrivateIdentifier(node.AsPrivateIdentifier())

	// Parse tree nodes
	// Names
	case ast.KindQualifiedName:
		p.emitQualifiedName(node.AsQualifiedName())
	case ast.KindComputedPropertyName:
		p.emitComputedPropertyName(node.AsComputedPropertyName())

	// Signature elements
	case ast.KindTypeParameter:
		p.emitTypeParameter(node.AsTypeParameterDeclaration())
	case ast.KindParameter:
		p.emitParameter(node.AsParameterDeclaration())
	case ast.KindDecorator:
		p.emitDecorator(node.AsDecorator())

	// Type members
	case ast.KindPropertySignature:
		p.emitPropertySignature(node.AsPropertySignatureDeclaration())
	case ast.KindPropertyDeclaration:
		p.emitPropertyDeclaration(node.AsPropertyDeclaration())
	case ast.KindMethodSignature:
		p.emitMethodSignature(node.AsMethodSignatureDeclaration())
	case ast.KindMethodDeclaration:
		p.emitMethodDeclaration(node.AsMethodDeclaration())
	case ast.KindClassStaticBlockDeclaration:
		p.emitClassStaticBlockDeclaration(node.AsClassStaticBlockDeclaration())
	case ast.KindConstructor:
		p.emitConstructor(node.AsConstructorDeclaration())
	case ast.KindGetAccessor:
		p.emitGetAccessorDeclaration(node.AsGetAccessorDeclaration())
	case ast.KindSetAccessor:
		p.emitSetAccessorDeclaration(node.AsSetAccessorDeclaration())
	case ast.KindCallSignature:
		p.emitCallSignature(node.AsCallSignatureDeclaration())
	case ast.KindConstructSignature:
		p.emitConstructSignature(node.AsConstructSignatureDeclaration())
	case ast.KindIndexSignature:
		p.emitIndexSignature(node.AsIndexSignatureDeclaration())

	// Binding patterns
	case ast.KindObjectBindingPattern:
		p.emitObjectBindingPattern(node.AsBindingPattern())
	case ast.KindArrayBindingPattern:
		p.emitArrayBindingPattern(node.AsBindingPattern())
	case ast.KindBindingElement:
		p.emitBindingElement(node.AsBindingElement())

	// Misc
	case ast.KindTemplateSpan:
		p.emitTemplateSpan(node.AsTemplateSpan())
	case ast.KindSemicolonClassElement:
		p.emitSemicolonClassElement(node)

	// Declarations (non-statement)
	case ast.KindVariableDeclaration:
		p.emitVariableDeclaration(node.AsVariableDeclaration())
	case ast.KindVariableDeclarationList:
		p.emitVariableDeclarationList(node.AsVariableDeclarationList())
	case ast.KindModuleBlock:
		p.emitModuleBlock(node.AsModuleBlock())
	case ast.KindCaseBlock:
		p.emitCaseBlock(node.AsCaseBlock())
	case ast.KindImportClause:
		p.emitImportClause(node.AsImportClause())
	case ast.KindNamespaceImport:
		p.emitNamespaceImport(node.AsNamespaceImport())
	case ast.KindNamespaceExport:
		p.emitNamespaceExport(node.AsNamespaceExport())
	case ast.KindNamedImports:
		p.emitNamedImports(node.AsNamedImports())
	case ast.KindImportSpecifier:
		p.emitImportSpecifier(node.AsImportSpecifier())
	case ast.KindNamedExports:
		p.emitNamedExports(node.AsNamedExports())
	case ast.KindExportSpecifier:
		p.emitExportSpecifier(node.AsExportSpecifier())
	case ast.KindImportAttributes:
		p.emitImportAttributes(node.AsImportAttributes())
	case ast.KindImportAttribute:
		p.emitImportAttribute(node.AsImportAttribute())

	// Module references
	case ast.KindExternalModuleReference:
		p.emitExternalModuleReference(node.AsExternalModuleReference())

	// JSX (non-expression)
	case ast.KindJsxText:
		p.emitJsxText(node.AsJsxText())
	case ast.KindJsxOpeningElement:
		p.emitJsxOpeningElement(node.AsJsxOpeningElement())
	case ast.KindJsxOpeningFragment:
		p.emitJsxOpeningFragment(node)
	case ast.KindJsxClosingElement:
		p.emitJsxClosingElement(node.AsJsxClosingElement())
	case ast.KindJsxClosingFragment:
		p.emitJsxClosingFragment(node)
	case ast.KindJsxAttribute:
		p.emitJsxAttribute(node.AsJsxAttribute())
	case ast.KindJsxAttributes:
		p.emitJsxAttributes(node.AsJsxAttributes())
	case ast.KindJsxSpreadAttribute:
		p.emitJsxSpreadAttribute(node.AsJsxSpreadAttribute())
	case ast.KindJsxExpression:
		p.emitJsxExpression(node.AsJsxExpression())
	case ast.KindJsxNamespacedName:
		p.emitJsxNamespacedName(node.AsJsxNamespacedName())

	// Clauses
	case ast.KindCaseClause:
		p.emitCaseClause(node.AsCaseOrDefaultClause())
	case ast.KindDefaultClause:
		p.emitDefaultClause(node.AsCaseOrDefaultClause())
	case ast.KindHeritageClause:
		p.emitHeritageClause(node.AsHeritageClause())
	case ast.KindCatchClause:
		p.emitCatchClause(node.AsCatchClause())

	// Property assignments
	case ast.KindPropertyAssignment:
		p.emitPropertyAssignment(node.AsPropertyAssignment())
	case ast.KindShorthandPropertyAssignment:
		p.emitShorthandPropertyAssignment(node.AsShorthandPropertyAssignment())
	case ast.KindSpreadAssignment:
		p.emitSpreadAssignment(node.AsSpreadAssignment())

	// Enum
	case ast.KindEnumMember:
		p.emitEnumMember(node.AsEnumMember())

		// Top-level nodes
	case ast.KindSourceFile:
		p.emitSourceFile(node.File())

	// Transformation nodes
	case ast.KindNotEmittedTypeElement:
		p.emitNotEmittedTypeElement(node)

	default:
		switch {
		case store.IsTypeNode(node):
			p.emitTypeNodeOutsideExtends(node)
		case store.IsStatement(node):
			p.emitStatement(node)
		case store.IsExpression(node):
			p.emitExpression(node, ast.OperatorPrecedenceLowest)
		case ast.IsKeywordKind(node.Kind()):
			p.emitKeywordNode(node)
		case ast.IsPunctuationKind(node.Kind()):
			p.emitPunctuationNode(node)
		case ast.IsJSDocKind(node.Kind()):
			p.emitJSDocNode(node)
		default:
			panic(fmt.Sprintf("unhandled Node: %v", node.Kind()))
		}
	}

	p.currentSourceFile = savedCurrentSourceFile
	p.writer = savedWriter
	p.uniqueHelperNames = savedUniqueHelperNames
	p.sourceMapsDisabled = savedSourceMapsDisabled
	p.sourceMapGenerator = savedSourceMapGenerator
	p.sourceMapSource = savedSourceMapSource
	p.sourceMapSourceIndex = savedSourceMapSourceIndex
	p.sourceMapLineCharCache = savedSourceMapLineCharCache
}

func (p *Printer) emitCommentsBeforeNode(node store.Node) *commentState {
	if !p.shouldEmitComments(node) {
		return nil
	}

	emitFlags := p.emitContext.EmitFlags(node)
	commentRange := p.emitContext.CommentRange(node)
	containerPos := p.containerPos
	containerEnd := p.containerEnd
	declarationListContainerEnd := p.declarationListContainerEnd

	// Emit leading comments
	p.emitLeadingCommentsOfNode(node, emitFlags, commentRange)
	p.emitLeadingSyntheticCommentsOfNode(node, emitFlags)
	if emitFlags&EFNoNestedComments != 0 {
		p.commentsDisabled = true
	}

	c := p.commentStateArena.New()
	*c = commentState{emitFlags, commentRange, containerPos, containerEnd, declarationListContainerEnd}
	return c
}

func (p *Printer) emitCommentsAfterNode(node store.Node, state *commentState) {
	if state == nil {
		return
	}

	emitFlags := state.emitFlags
	commentRange := state.commentRange
	containerPos := state.containerPos
	containerEnd := state.containerEnd
	declarationListContainerEnd := state.declarationListContainerEnd

	// Emit trailing comments
	if emitFlags&EFNoNestedComments != 0 {
		p.commentsDisabled = false
	}

	p.emitTrailingSyntheticCommentsOfNode(node, emitFlags)
	p.emitTrailingCommentsOfNode(node, emitFlags, commentRange, containerPos, containerEnd, declarationListContainerEnd)

	// Preserve comments from erased type annotation
	if typeNode := p.emitContext.GetTypeNode(node); !typeNode.IsNil() {
		p.emitTrailingCommentsOfNode(node, emitFlags, typeNode.Loc(), containerPos, containerEnd, declarationListContainerEnd)
	}
}

func (p *Printer) emitCommentsBeforeToken(token ast.Kind, pos int, contextNode store.Node, flags tokenEmitFlags) (*commentState, int) {
	if flags&tefNoComments != 0 || p.commentsDisabled {
		// Still skip trivia so that the returned pos correctly identifies the token position.
		// This is needed for trailing source map positions (writeTokenText advances pos by token length).
		if p.currentSourceFile != nil && !ast.PositionIsSynthesized(pos) {
			pos = scanner.SkipTrivia(p.currentSourceFile.Text(), pos)
		}
		return nil, pos
	}

	startPos := pos
	if p.currentSourceFile != nil {
		pos = scanner.SkipTrivia(p.currentSourceFile.Text(), startPos)
	}

	node := p.emitContext.ParseNode(contextNode)
	isSimilarNode := !node.IsNil() && node.Kind() == contextNode.Kind()
	if !isSimilarNode {
		return nil, pos
	}

	if int(contextNode.Pos()) != startPos {
		indentLeading := flags&tefIndentLeadingComments != 0
		needsIndent := indentLeading && p.currentSourceFile != nil && !PositionsAreOnSameLine(startPos, pos, p.currentSourceFile)
		p.increaseIndentIf(needsIndent)
		p.emitLeadingComments(startPos, false /*elided*/)
		p.decreaseIndentIf(needsIndent)
	}

	return p.commentStateArena.New(), pos
}

func (p *Printer) emitCommentsAfterToken(token ast.Kind, pos int, contextNode store.Node, state *commentState) {
	if state == nil {
		return
	}

	if int(contextNode.End()) != pos {
		isJsxExprContext := contextNode.Kind() == ast.KindJsxExpression
		p.emitTrailingComments(pos, core.IfElse(isJsxExprContext, commentSeparatorNone, commentSeparatorBefore))
	}
}

func (p *Printer) emitDetachedCommentsBeforeStatementList(node store.Node, detachedRange core.TextRange) *commentState {
	if !p.shouldEmitDetachedComments(node) {
		return nil
	}

	emitFlags := p.emitContext.EmitFlags(node)
	containerPos := p.containerPos
	containerEnd := p.containerEnd
	declarationListContainerEnd := p.declarationListContainerEnd
	skipLeadingComments := ast.PositionIsSynthesized(detachedRange.Pos()) || emitFlags&EFNoLeadingComments != 0

	if !skipLeadingComments {
		p.emitDetachedCommentsAndUpdateCommentsInfo(detachedRange)
	}

	if emitFlags&EFNoNestedComments != 0 {
		p.commentsDisabled = true
	}

	return &commentState{emitFlags, detachedRange, containerPos, containerEnd, declarationListContainerEnd}
}

func (p *Printer) emitDetachedCommentsAfterStatementList(node store.Node, detachedRange core.TextRange, state *commentState) {
	if state == nil {
		return
	}

	emitFlags := state.emitFlags
	skipTrailingComments := p.commentsDisabled || ast.PositionIsSynthesized(detachedRange.End()) || emitFlags&EFNoTrailingComments != 0

	if !skipTrailingComments {
		hasWrittenComment := p.emitLeadingComments(detachedRange.End(), false /*elided*/)
		if hasWrittenComment && !p.writer.IsAtStartOfLine() {
			p.writeLine()
		}
	}
}

func (p *Printer) emitLeadingCommentsOfNode(node store.Node, emitFlags EmitFlags, commentRange core.TextRange) {
	pos := commentRange.Pos()
	end := commentRange.End()

	// Save current container state on the stack.
	if (!ast.PositionIsSynthesized(pos) || !ast.PositionIsSynthesized(end)) && pos != end {
		// We have to explicitly check that the node is JsxText because if the compilerOptions.jsx is "preserve" we will not do any transformation.
		// It is expensive to walk entire tree just to set one kind of node to have no comments.
		skipLeadingComments := ast.PositionIsSynthesized(pos) || emitFlags&EFNoLeadingComments != 0 || node.Kind() == ast.KindJsxText
		skipTrailingComments := ast.PositionIsSynthesized(end) || emitFlags&EFNoTrailingComments != 0 || node.Kind() == ast.KindJsxText

		// Emit leading comments if the position is not synthesized and the node
		// has not opted out from emitting leading comments.
		if !skipLeadingComments {
			p.emitLeadingComments(pos, node.Kind() == ast.KindNotEmittedStatement /*elided*/)
		}

		if !skipLeadingComments || (pos >= 0 && (emitFlags&EFNoLeadingComments) != 0) {
			// Advance the container position if comments get emitted or if they've been disabled explicitly using NoLeadingComments.
			p.containerPos = pos
		}

		if !skipTrailingComments || (end >= 0 && (emitFlags&EFNoTrailingComments) != 0) {
			// Advance the container end if comments get emitted or if they've been disabled explicitly using NoTrailingComments.
			p.containerEnd = end

			// To avoid invalid comment emit in a down-level binding pattern, we
			// keep track of the last declaration list container's end
			if node.Kind() == ast.KindVariableDeclarationList {
				p.declarationListContainerEnd = end
			}
		}
	}
}

func (p *Printer) emitTrailingCommentsOfNode(node store.Node, emitFlags EmitFlags, commentRange core.TextRange, containerPos int, containerEnd int, declarationListContainerEnd int) {
	pos := commentRange.Pos()
	end := commentRange.End()
	skipTrailingComments := end < 0 || (emitFlags&EFNoTrailingComments) != 0 || node.Kind() == ast.KindJsxText
	if (!ast.PositionIsSynthesized(pos) || !ast.PositionIsSynthesized(end)) && pos != end {
		// Restore previous container state.
		p.containerPos = containerPos
		p.containerEnd = containerEnd
		p.declarationListContainerEnd = declarationListContainerEnd

		// Emit trailing comments if the position is not synthesized and the node
		// has not opted out from emitting leading comments and is an emitted node.
		if !skipTrailingComments && node.Kind() != ast.KindNotEmittedStatement {
			p.emitTrailingComments(end, commentSeparatorBefore)
		}
	}
}

func (p *Printer) emitLeadingSyntheticCommentsOfNode(node store.Node, emitFlags EmitFlags) {
	if emitFlags&EFNoLeadingComments != 0 {
		return
	}
	synth := p.emitContext.GetSyntheticLeadingComments(node)
	for _, c := range synth {
		p.emitLeadingSynthesizedComment(c)
	}
}

func (p *Printer) emitLeadingSynthesizedComment(comment SynthesizedComment) {
	if comment.HasLeadingNewLine || comment.Kind == ast.KindSingleLineCommentTrivia {
		p.writer.WriteLine()
	}
	p.writeSynthesizedComment(comment)
	if comment.HasTrailingNewLine || comment.Kind == ast.KindSingleLineCommentTrivia {
		p.writer.WriteLine()
	} else {
		p.writer.WriteSpace(" ")
	}
}

func (p *Printer) emitTrailingSyntheticCommentsOfNode(node store.Node, emitFlags EmitFlags) {
	if emitFlags&EFNoTrailingComments != 0 {
		return
	}
	synth := p.emitContext.GetSyntheticTrailingComments(node)
	for _, c := range synth {
		p.emitTrailingSynthesizedComment(c)
	}
}

func (p *Printer) emitTrailingSynthesizedComment(comment SynthesizedComment) {
	if !p.writer.IsAtStartOfLine() {
		p.writer.WriteSpace(" ")
	}
	p.writeSynthesizedComment(comment)
	if comment.HasTrailingNewLine {
		p.writer.WriteLine()
	}
}

func formatSynthesizedComment(comment SynthesizedComment) string {
	if comment.Kind == ast.KindMultiLineCommentTrivia {
		return "/*" + comment.Text + "*/"
	}
	return "//" + comment.Text
}

func (p *Printer) writeSynthesizedComment(comment SynthesizedComment) {
	text := formatSynthesizedComment(comment)
	var lineMap []core.TextPos
	if comment.Kind == ast.KindMultiLineCommentTrivia {
		lineMap = core.ComputeECMALineStarts(text)
	}
	p.writeCommentRangeWorker(text, lineMap, comment.Kind, core.NewTextRange(0, len(text)))
}

func (p *Printer) emitLeadingComments(pos int, elided bool) bool {
	// Emit the leading comments only if the container's pos doesn't match because the container should take care of emitting these comments
	if p.commentsDisabled || p.currentSourceFile == nil || ast.PositionIsSynthesized(pos) || pos == p.containerPos {
		return false
	}

	tripleSlash := core.TSUnknown
	if !elided {
		if pos == 0 && p.currentSourceFile != nil && p.currentSourceFile.IsDeclarationFile {
			tripleSlash = core.TSFalse
		}
	} else if pos == 0 {
		// If the node will not be emitted in JS, remove all the comments(normal, pinned and ///) associated with the node,
		// unless it is a triple slash comment at the top of the file.
		// For Example:
		//      /// <reference-path ...>
		//      declare var x;
		//      /// <reference-path ...>
		//      interface F {}
		//  The first /// will NOT be removed while the second one will be removed even though both node will not be emitted
		tripleSlash = core.TSTrue
	} else {
		return false
	}

	// skip detached comments
	if p.detachedCommentsInfo.Len() > 0 {
		if info := p.detachedCommentsInfo.Peek(); info.nodePos == pos {
			pos = p.detachedCommentsInfo.Pop().detachedCommentEndPos
		}
	}

	var comments []ast.CommentRange
	for comment := range storescanner.GetLeadingCommentRanges(p.emitContext.Factory.Factory, p.currentSourceFile.Text(), pos) {
		if p.shouldWriteComment(comment) && p.shouldEmitCommentIfTripleSlash(comment, tripleSlash) {
			comments = append(comments, comment)
		}
	}

	if len(comments) > 0 && p.shouldEmitNewLineBeforeLeadingCommentOfPosition(pos, comments[0].Pos()) {
		p.writeLine()
	}

	// Leading comments are emitted as /*leading comment1*/space/*leading comment*/space
	return p.emitComments(comments, commentSeparatorAfter)
}

func (p *Printer) shouldEmitCommentIfTripleSlash(comment ast.CommentRange, tripleSlash core.Tristate) bool {
	switch tripleSlash {
	case core.TSTrue:
		return p.isTripleSlashComment(comment)
	case core.TSFalse:
		return !p.isTripleSlashComment(comment)
	default:
		return true
	}
}

func (p *Printer) shouldEmitNewLineBeforeLeadingCommentOfPosition(pos int, commentPos int) bool {
	// If the leading comments start on different line than the start of node, write new line
	return p.currentSourceFile != nil &&
		pos != commentPos &&
		scanner.ComputeLineOfPosition(p.currentSourceFile.ECMALineMap(), pos) != scanner.ComputeLineOfPosition(p.currentSourceFile.ECMALineMap(), commentPos)
}

func (p *Printer) emitLeadingCommentsOfPosition(pos int) {
	if p.commentsDisabled || pos == -1 {
		return
	}

	p.emitLeadingComments(pos, false /*elided*/)
}

func (p *Printer) emitTrailingComments(pos int, commentSeparator commentSeparator) {
	if p.commentsDisabled {
		return
	}
	// Emit the trailing comments only if the container's end doesn't match because the container should take care of emitting these comments
	if p.commentsDisabled || p.currentSourceFile == nil || p.containerEnd != -1 && (pos == p.containerEnd || pos == p.declarationListContainerEnd) {
		return
	}

	var comments []ast.CommentRange
	for comment := range storescanner.GetTrailingCommentRanges(p.emitContext.Factory.Factory, p.currentSourceFile.Text(), pos) {
		if p.shouldWriteComment(comment) {
			comments = append(comments, comment)
		}
	}

	// trailing comments are normally emitted as space/*trailing comment1*/space/*trailing comment2*/
	p.emitComments(comments, commentSeparator)
}

func (p *Printer) emitTrailingCommentsOfPosition(pos int, prefixSpace bool, forceNoNewline bool) {
	if p.commentsDisabled || p.currentSourceFile == nil {
		return
	}
	if p.containerEnd != -1 && (pos == p.containerEnd || pos == p.declarationListContainerEnd) {
		return
	}

	var comments []ast.CommentRange
	for comment := range storescanner.GetTrailingCommentRanges(p.emitContext.Factory.Factory, p.currentSourceFile.Text(), pos) {
		comments = append(comments, comment)
	}
	if len(comments) == 0 {
		return
	}

	for _, comment := range comments {
		if prefixSpace {
			if !p.shouldWriteComment(comment) {
				continue
			}
			if !p.writer.IsAtStartOfLine() {
				p.writeSpace()
			}
			p.emitComment(comment)
			if comment.HasTrailingNewLine {
				p.writeLine()
			}
			continue
		}

		p.emitComment(comment)
		switch {
		case forceNoNewline:
			if comment.Kind == ast.KindSingleLineCommentTrivia {
				p.writeLine()
			}
		case comment.HasTrailingNewLine:
			p.writeLine()
		default:
			p.writeSpace()
		}
	}
}

func (p *Printer) emitDetachedCommentsAndUpdateCommentsInfo(textRange core.TextRange) {
	if p.currentSourceFile == nil {
		return
	}
	if currentDetachedCommentInfo, ok := p.emitDetachedComments(textRange); ok {
		p.detachedCommentsInfo.Push(currentDetachedCommentInfo)
	}
}

func (p *Printer) emitDetachedComments(textRange core.TextRange) (result detachedCommentsInfo, hasResult bool) {
	if p.currentSourceFile == nil {
		return result, hasResult
	}

	text := p.currentSourceFile.Text()
	lineMap := p.currentSourceFile.ECMALineMap()

	var leadingComments []ast.CommentRange
	if p.commentsDisabled {
		// removeComments is true, only reserve pinned comment at the top of file
		// For example:
		//      /*! Pinned Comment */
		//
		//      var x = 10;
		if textRange.Pos() == 0 {
			for comment := range storescanner.GetLeadingCommentRanges(p.emitContext.Factory.Factory, text, textRange.Pos()) {
				if IsPinnedComment(text, comment) {
					leadingComments = append(leadingComments, comment)
				}
			}
		}
	} else {
		// removeComments is false, just get detached as normal and bypass the process to filter comment
		leadingComments = slices.Collect(storescanner.GetLeadingCommentRanges(p.emitContext.Factory.Factory, text, textRange.Pos()))
	}

	if len(leadingComments) > 0 {
		var detachedComments []ast.CommentRange
		var lastComment ast.CommentRange
		for i, comment := range leadingComments {
			if i > 0 {
				lastCommentLine := scanner.ComputeLineOfPosition(lineMap, lastComment.End())
				commentLine := scanner.ComputeLineOfPosition(lineMap, comment.Pos())

				if commentLine >= lastCommentLine+2 {
					// There was a blank line between the last comment and this comment.  This
					// comment is not part of the copyright comments.  Return what we have so
					// far.
					break
				}
			}

			detachedComments = append(detachedComments, comment)
			lastComment = comment
		}

		if len(detachedComments) > 0 {
			// All comments look like they could have been part of the copyright header.  Make
			// sure there is at least one blank line between it and the node.  If not, it's not
			// a copyright header.
			lastCommentLine := scanner.ComputeLineOfPosition(lineMap, core.LastOrNil(detachedComments).End())
			nodeLine := scanner.ComputeLineOfPosition(lineMap, scanner.SkipTrivia(text, textRange.Pos()))
			if nodeLine >= lastCommentLine+2 {
				// Valid detachedComments

				// Filter to only comments that should be written (e.g., JSDoc-style in declaration emit)
				var commentsToEmit []ast.CommentRange
				for _, comment := range detachedComments {
					if p.shouldWriteComment(comment) {
						commentsToEmit = append(commentsToEmit, comment)
					}
				}

				if len(commentsToEmit) > 0 {
					if p.shouldEmitNewLineBeforeLeadingCommentOfPosition(textRange.Pos(), commentsToEmit[0].Pos()) {
						p.writeLine()
					}

					p.emitComments(commentsToEmit, commentSeparatorAfter)
				}
				result = detachedCommentsInfo{nodePos: textRange.Pos(), detachedCommentEndPos: core.LastOrNil(detachedComments).End()}
				hasResult = true
			}
		}
	}
	return result, hasResult
}

type commentSeparator uint32

const (
	commentSeparatorNone commentSeparator = iota
	commentSeparatorBefore
	commentSeparatorAfter
)

func (p *Printer) emitComments(comments []ast.CommentRange, commentSeparator commentSeparator) bool {
	interveningSeparator := false
	if len(comments) == 0 {
		return false
	}

	if commentSeparator == commentSeparatorBefore {
		p.writeSpace()
	}

	for _, comment := range comments {
		if interveningSeparator {
			p.writeSpace()
			interveningSeparator = false
		}

		p.emitComment(comment)

		if comment.Kind == ast.KindSingleLineCommentTrivia || comment.HasTrailingNewLine && commentSeparator != commentSeparatorNone {
			p.writeLine()
		} else {
			interveningSeparator = commentSeparator != commentSeparatorNone
		}
	}

	if interveningSeparator && commentSeparator == commentSeparatorAfter {
		p.writeSpace()
	}

	return true
}

func (p *Printer) emitComment(comment ast.CommentRange) {
	p.emitPos(comment.Pos())
	p.writeCommentRange(comment)
	p.emitPos(comment.End())
}

func (p *Printer) isTripleSlashComment(comment ast.CommentRange) bool {
	return p.currentSourceFile != nil &&
		IsRecognizedTripleSlashComment(p.currentSourceFile.Text(), comment)
}

func (p *Printer) setSourceMapSource(source sourcemap.Source) {
	if p.sourceMapsDisabled {
		return
	}

	p.sourceMapSource = source
	p.sourceMapLineCharCache = newLineCharacterCache(source)
	if p.mostRecentSourceMapSource == source {
		p.sourceMapSourceIndex = p.mostRecentSourceMapSourceIndex
		return
	}

	p.sourceMapSourceIsJson = tspath.FileExtensionIs(source.FileName(), tspath.ExtensionJson)
	if p.sourceMapSourceIsJson {
		return
	}

	p.sourceMapSourceIndex = p.sourceMapGenerator.AddSource(source.FileName())
	if p.Options.InlineSources {
		if err := p.sourceMapGenerator.SetSourceContent(p.sourceMapSourceIndex, source.Text()); err != nil {
			panic(err)
		}
	}

	p.mostRecentSourceMapSource = source
	p.mostRecentSourceMapSourceIndex = p.sourceMapSourceIndex
}

func (p *Printer) emitPos(pos int) {
	if p.sourceMapsDisabled || p.sourceMapSource == nil || p.sourceMapGenerator == nil || p.sourceMapSourceIsJson || ast.PositionIsSynthesized(pos) {
		return
	}

	source := p.sourceMapSource
	sourceIndex := p.sourceMapSourceIndex
	lineCharCache := p.sourceMapLineCharCache
	if p.MapSourcePosition != nil {
		mappedSource, mappedPos, ok := p.MapSourcePosition(source, pos)
		if !ok {
			if err := p.sourceMapGenerator.AddGeneratedMapping(p.writer.GetLine(), p.writer.GetColumn()); err != nil {
				panic(err)
			}
			return
		}
		pos = mappedPos
		if mappedSource != source {
			savedSource := p.sourceMapSource
			savedSourceIndex := p.sourceMapSourceIndex
			savedSourceIsJson := p.sourceMapSourceIsJson
			savedLineCharCache := p.sourceMapLineCharCache
			p.setSourceMapSource(mappedSource)
			sourceIndex = p.sourceMapSourceIndex
			lineCharCache = p.sourceMapLineCharCache
			p.sourceMapSource = savedSource
			p.sourceMapSourceIndex = savedSourceIndex
			p.sourceMapSourceIsJson = savedSourceIsJson
			p.sourceMapLineCharCache = savedLineCharCache
		}
	}

	sourceLine, sourceCharacter := lineCharCache.getLineAndCharacter(pos)
	if err := p.sourceMapGenerator.AddSourceMapping(
		p.writer.GetLine(),
		p.writer.GetColumn(),
		sourceIndex,
		sourceLine,
		sourceCharacter,
	); err != nil {
		panic(err)
	}
}

func (p *Printer) emitSourcePos(source sourcemap.Source, pos int) {
	if source != p.sourceMapSource {
		savedSourceMapSource := p.sourceMapSource
		savedSourceMapSourceIndex := p.sourceMapSourceIndex
		savedSourceMapLineCharCache := p.sourceMapLineCharCache
		p.setSourceMapSource(source)
		p.emitPos(pos)
		p.sourceMapSource = savedSourceMapSource
		p.sourceMapSourceIndex = savedSourceMapSourceIndex
		p.sourceMapLineCharCache = savedSourceMapLineCharCache
	} else {
		p.emitPos(pos)
	}
}

func (p *Printer) emitSourceMapsBeforeNode(node store.Node) *sourceMapState {
	if !p.shouldEmitSourceMaps(node) {
		return nil
	}

	emitFlags := p.emitContext.EmitFlags(node)
	loc := p.emitContext.SourceMapRange(node)

	if !store.IsNotEmittedStatement(node) &&
		emitFlags&EFNoLeadingSourceMap == 0 &&
		p.currentSourceFile != nil &&
		!ast.PositionIsSynthesized(loc.Pos()) {
		p.emitSourcePos(p.sourceMapSource, scanner.SkipTrivia(p.currentSourceFile.Text(), loc.Pos()))
	}

	if emitFlags&EFNoNestedSourceMaps != 0 {
		p.sourceMapsDisabled = true
	}

	state := p.sourceMapStateArena.New()
	*state = sourceMapState{emitFlags, loc, false}
	return state
}

func (p *Printer) emitSourceMapsAfterNode(node store.Node, previousState *sourceMapState) {
	if previousState == nil {
		return
	}

	emitFlags := previousState.emitFlags
	loc := previousState.sourceMapRange

	if emitFlags&EFNoNestedSourceMaps != 0 {
		p.sourceMapsDisabled = false
	}

	if !store.IsNotEmittedStatement(node) &&
		emitFlags&EFNoTrailingSourceMap == 0 &&
		!ast.PositionIsSynthesized(loc.End()) {
		p.emitSourcePos(p.sourceMapSource, loc.End())
	}
}

func (p *Printer) emitSourceMapsBeforeToken(token ast.Kind, pos int, contextNode store.Node, flags tokenEmitFlags) *sourceMapState {
	if !p.shouldEmitTokenSourceMaps(token, pos, contextNode, flags) {
		return nil
	}

	emitFlags := p.emitContext.EmitFlags(contextNode)
	loc, hasLoc := p.emitContext.TokenSourceMapRange(contextNode, token)
	if hasLoc {
		pos = loc.Pos()
	}
	if pos >= 0 && p.currentSourceFile != nil {
		pos = scanner.SkipTrivia(p.currentSourceFile.Text(), pos)
	}
	if emitFlags&EFNoTokenLeadingSourceMaps == 0 && pos >= 0 {
		p.emitSourcePos(p.sourceMapSource, pos)
	}

	state := p.sourceMapStateArena.New()
	*state = sourceMapState{emitFlags, loc, hasLoc}
	return state
}

func (p *Printer) emitSourceMapsAfterToken(token ast.Kind, pos int, contextNode store.Node, previousState *sourceMapState) {
	if previousState == nil {
		return
	}

	emitFlags := previousState.emitFlags
	loc := previousState.sourceMapRange
	hasLoc := previousState.hasTokenSourceMapRange
	if emitFlags&EFNoTokenTrailingSourceMaps == 0 {
		if hasLoc {
			pos = loc.End()
		}
		if pos >= 0 {
			p.emitSourcePos(p.sourceMapSource, pos)
		}
	}
}

func (p *Printer) shouldReuseTempVariableScope(node store.Node) bool {
	return !node.IsNil() && p.emitContext.EmitFlags(node)&EFReuseTempVariableScope != 0
}

func (p *Printer) pushNameGenerationScope(node store.Node) {
	p.nameGenerator.PushScope(p.shouldReuseTempVariableScope(node))
}

func (p *Printer) popNameGenerationScope(node store.Node) {
	p.nameGenerator.PopScope(p.shouldReuseTempVariableScope(node))
}

func (p *Printer) generateAllNames(nodes store.List) {
	if nodes.IsNil() {
		return
	}
	for i := range nodes.Len() {
		node := nodes.At(i)
		p.generateNames(node)
	}
}

func (p *Printer) generateNames(node store.Node) {
	if node.IsNil() {
		return
	}

	switch node.Kind() {
	case ast.KindBlock, ast.KindCaseClause, ast.KindDefaultClause:
		p.generateAllNames(node.StatementList())
	case ast.KindLabeledStatement, ast.KindWithStatement, ast.KindDoStatement, ast.KindWhileStatement:
		p.generateNames(node.Statement())
	case ast.KindIfStatement:
		p.generateNames(node.AsIfStatement().ThenStatement())
		p.generateNames(node.AsIfStatement().ElseStatement())
	case ast.KindForStatement, ast.KindForOfStatement, ast.KindForInStatement:
		p.generateNames(node.Initializer())
		p.generateNames(node.Statement())
	case ast.KindSwitchStatement:
		p.generateNames(node.AsSwitchStatement().CaseBlock())
	case ast.KindCaseBlock:
		p.generateAllNames(node.AsCaseBlock().Clauses())
	case ast.KindTryStatement:
		p.generateNames(node.AsTryStatement().TryBlock())
		p.generateNames(node.AsTryStatement().CatchClause())
		p.generateNames(node.AsTryStatement().FinallyBlock())
	case ast.KindCatchClause:
		p.generateNames(node.AsCatchClause().VariableDeclaration())
		p.generateNames(node.AsCatchClause().Block())
	case ast.KindVariableStatement:
		p.generateNames(node.AsVariableStatement().DeclarationList())
	case ast.KindVariableDeclarationList:
		p.generateAllNames(node.AsVariableDeclarationList().Declarations())
	case ast.KindVariableDeclaration, ast.KindParameter, ast.KindBindingElement, ast.KindClassDeclaration:
		p.generateNameIfNeeded(node.Name())
	case ast.KindFunctionDeclaration:
		p.generateNameIfNeeded(node.Name())
		if p.shouldReuseTempVariableScope(node) {
			p.generateAllNames(node.AsFunctionDeclaration().Parameters())
			p.generateNames(node.AsFunctionDeclaration().Body())
		}
	case ast.KindObjectBindingPattern, ast.KindArrayBindingPattern:
		p.generateAllNames(node.ElementList())
	case ast.KindImportDeclaration, ast.KindJSImportDeclaration:
		p.generateNames(node.AsImportDeclaration().ImportClause())
	case ast.KindImportClause:
		p.generateNameIfNeeded(node.AsImportClause().Name())
		p.generateNames(node.AsImportClause().NamedBindings())
	case ast.KindNamespaceImport, ast.KindNamespaceExport:
		p.generateNameIfNeeded(node.Name())
	case ast.KindNamedImports:
		p.generateAllNames(node.ElementList())
	case ast.KindImportSpecifier:
		n := node.AsImportSpecifier()
		if !n.PropertyName().IsNil() {
			p.generateNameIfNeeded(n.PropertyName())
		} else {
			p.generateNameIfNeeded(n.Name())
		}
	}
}

func (p *Printer) generateAllMemberNames(nodes store.List) {
	if nodes.IsNil() {
		return
	}
	for i := range nodes.Len() {
		node := nodes.At(i)
		p.generateMemberNames(node)
	}
}

func (p *Printer) generateMemberNames(node store.Node) {
	if node.IsNil() {
		return
	}
	switch node.Kind() {
	case ast.KindPropertyAssignment,
		ast.KindShorthandPropertyAssignment,
		ast.KindPropertyDeclaration,
		ast.KindPropertySignature,
		ast.KindMethodDeclaration,
		ast.KindMethodSignature,
		ast.KindGetAccessor,
		ast.KindSetAccessor:
		p.generateNameIfNeeded(node.Name())
	}
}

func (p *Printer) generateNameIfNeeded(name store.Node) {
	if !name.IsNil() {
		if store.IsMemberName(name) {
			p.generateName(name)
		} else if store.IsBindingPattern(name) {
			p.generateNames(name)
		}
	}
}

func (p *Printer) generateName(name store.Node) {
	_ = p.nameGenerator.GenerateName(name)
}

func (p *Printer) isFileLevelUniqueNameInCurrentFile(name string, _ bool) bool {
	if p.currentSourceFile != nil {
		return p.emitContext.IsFileLevelUniqueName(p.currentSourceFile, name, p.HasGlobalName)
	} else {
		return true
	}
}

func (p *Printer) enterNode(node store.Node) printerState {
	state := printerState{}

	if p.OnBeforeEmitNode != nil {
		p.OnBeforeEmitNode(node)
	}

	state.commentState = p.emitCommentsBeforeNode(node)
	state.sourceMapState = p.emitSourceMapsBeforeNode(node)
	return state
}

func (p *Printer) exitNode(node store.Node, previousState printerState) {
	p.emitSourceMapsAfterNode(node, previousState.sourceMapState)
	p.emitCommentsAfterNode(node, previousState.commentState)

	if p.OnAfterEmitNode != nil {
		p.OnAfterEmitNode(node)
	}
}

func (p *Printer) enterTokenNode(node store.Node, flags tokenEmitFlags) printerState {
	state := printerState{}

	if p.OnBeforeEmitToken != nil {
		p.OnBeforeEmitToken(node)
	}

	if flags&tefNoComments == 0 {
		state.commentState = p.emitCommentsBeforeNode(node)
	}
	if flags&tefNoSourceMaps == 0 {
		state.sourceMapState = p.emitSourceMapsBeforeNode(node)
	}
	return state
}

func (p *Printer) exitTokenNode(node store.Node, previousState printerState) {
	p.emitSourceMapsAfterNode(node, previousState.sourceMapState)
	p.emitCommentsAfterNode(node, previousState.commentState)

	if p.OnAfterEmitToken != nil {
		p.OnAfterEmitToken(node)
	}
}

type tokenEmitFlags uint32

const (
	tefNoComments tokenEmitFlags = 1 << iota
	tefIndentLeadingComments
	tefNoSourceMaps

	tefNone tokenEmitFlags = 0
)

func (p *Printer) enterToken(token ast.Kind, pos int, contextNode store.Node, flags tokenEmitFlags) (printerState, int) {
	state := printerState{}
	state.commentState, pos = p.emitCommentsBeforeToken(token, pos, contextNode, flags)
	state.sourceMapState = p.emitSourceMapsBeforeToken(token, pos, contextNode, flags)
	return state, pos
}

func (p *Printer) exitToken(token ast.Kind, pos int, contextNode store.Node, previousState printerState) {
	p.emitSourceMapsAfterToken(token, pos, contextNode, previousState.sourceMapState)
	p.emitCommentsAfterToken(token, pos, contextNode, previousState.commentState)
}

type ListFormat int

const (
	LFNone ListFormat = 0

	// Line separators
	LFSingleLine    ListFormat = 0      // Prints the list on a single line (default).
	LFMultiLine     ListFormat = 1 << 0 // Prints the list on multiple lines.
	LFPreserveLines ListFormat = 1 << 1 // Prints the list using line preservation if possible.
	LFLinesMask     ListFormat = LFSingleLine | LFMultiLine | LFPreserveLines

	// Delimiters
	LFNotDelimited       ListFormat = 0      // There is no delimiter between list items (default).
	LFBarDelimited       ListFormat = 1 << 2 // Each list item is space-and-bar (" |") delimited.
	LFAmpersandDelimited ListFormat = 1 << 3 // Each list item is space-and-ampersand (" &") delimited.
	LFCommaDelimited     ListFormat = 1 << 4 // Each list item is comma (",") delimited.
	LFAsteriskDelimited  ListFormat = 1 << 5 // Each list item is asterisk ("\n *") delimited, used with JSDoc.
	LFDelimitersMask     ListFormat = LFBarDelimited | LFAmpersandDelimited | LFCommaDelimited | LFAsteriskDelimited

	LFAllowTrailingComma ListFormat = 1 << 6 // Write a trailing comma (",") if present.

	// Whitespace
	LFIndented             ListFormat = 1 << 7 // The list should be indented.
	LFSpaceBetweenBraces   ListFormat = 1 << 8 // Inserts a space after the opening brace and before the closing brace.
	LFSpaceBetweenSiblings ListFormat = 1 << 9 // Inserts a space between each sibling node.

	// Brackets/Braces
	LFBraces         ListFormat = 1 << 10 // The list is surrounded by "{" and "}".
	LFParenthesis    ListFormat = 1 << 11 // The list is surrounded by "(" and ")".
	LFAngleBrackets  ListFormat = 1 << 12 // The list is surrounded by "<" and ">".
	LFSquareBrackets ListFormat = 1 << 13 // The list is surrounded by "[" and "]".
	LFBracketsMask   ListFormat = LFBraces | LFParenthesis | LFAngleBrackets | LFSquareBrackets

	LFOptionalIfNil   ListFormat = 1 << 14 // Do not emit brackets if the list is nil.
	LFOptionalIfEmpty ListFormat = 1 << 15 // Do not emit brackets if the list is empty.
	LFOptional        ListFormat = LFOptionalIfNil | LFOptionalIfEmpty

	// Other
	LFPreferNewLine         ListFormat = 1 << 16 // Prefer adding a LineTerminator between synthesized nodes.
	LFNoTrailingNewLine     ListFormat = 1 << 17 // Do not emit a trailing NewLine for a MultiLine list.
	LFNoInterveningComments ListFormat = 1 << 18 // Do not emit comments between each node
	LFNoSpaceIfEmpty        ListFormat = 1 << 19 // If the literal is empty, do not add spaces between braces.
	LFSingleElement         ListFormat = 1 << 20
	LFSpaceAfterList        ListFormat = 1 << 21 // Add space after list

	// Precomputed Formats
	LFModifiers                    ListFormat = LFSingleLine | LFSpaceBetweenSiblings | LFNoInterveningComments | LFSpaceAfterList
	LFHeritageClauses              ListFormat = LFSingleLine | LFSpaceBetweenSiblings
	LFSingleLineTypeLiteralMembers ListFormat = LFSingleLine | LFSpaceBetweenBraces | LFSpaceBetweenSiblings
	LFMultiLineTypeLiteralMembers  ListFormat = LFMultiLine | LFIndented | LFOptionalIfEmpty

	LFSingleLineTupleTypeElements       ListFormat = LFCommaDelimited | LFSpaceBetweenSiblings | LFSingleLine
	LFMultiLineTupleTypeElements        ListFormat = LFCommaDelimited | LFIndented | LFSpaceBetweenSiblings | LFMultiLine
	LFUnionTypeConstituents             ListFormat = LFBarDelimited | LFSpaceBetweenSiblings | LFSingleLine
	LFIntersectionTypeConstituents      ListFormat = LFAmpersandDelimited | LFSpaceBetweenSiblings | LFSingleLine
	LFObjectBindingPatternElements      ListFormat = LFSingleLine | LFAllowTrailingComma | LFSpaceBetweenBraces | LFCommaDelimited | LFSpaceBetweenSiblings | LFNoSpaceIfEmpty
	LFArrayBindingPatternElements       ListFormat = LFSingleLine | LFAllowTrailingComma | LFCommaDelimited | LFSpaceBetweenSiblings | LFNoSpaceIfEmpty
	LFObjectLiteralExpressionProperties ListFormat = LFPreserveLines | LFCommaDelimited | LFSpaceBetweenSiblings | LFSpaceBetweenBraces | LFIndented | LFBraces | LFNoSpaceIfEmpty
	LFImportAttributes                  ListFormat = LFPreserveLines | LFCommaDelimited | LFSpaceBetweenSiblings | LFSpaceBetweenBraces | LFIndented | LFBraces | LFNoSpaceIfEmpty
	LFArrayLiteralExpressionElements    ListFormat = LFPreserveLines | LFCommaDelimited | LFSpaceBetweenSiblings | LFAllowTrailingComma | LFIndented | LFSquareBrackets
	LFCommaListElements                 ListFormat = LFCommaDelimited | LFSpaceBetweenSiblings | LFSingleLine
	LFCallExpressionArguments           ListFormat = LFCommaDelimited | LFSpaceBetweenSiblings | LFSingleLine | LFParenthesis
	LFNewExpressionArguments            ListFormat = LFCommaDelimited | LFSpaceBetweenSiblings | LFSingleLine | LFParenthesis | LFOptionalIfNil
	LFTemplateExpressionSpans           ListFormat = LFSingleLine | LFNoInterveningComments
	LFSingleLineBlockStatements         ListFormat = LFSpaceBetweenBraces | LFSpaceBetweenSiblings | LFSingleLine
	LFMultiLineBlockStatements          ListFormat = LFIndented | LFMultiLine
	LFVariableDeclarationList           ListFormat = LFCommaDelimited | LFSpaceBetweenSiblings | LFSingleLine
	LFSingleLineFunctionBodyStatements  ListFormat = LFSingleLine | LFSpaceBetweenSiblings | LFSpaceBetweenBraces
	LFMultiLineFunctionBodyStatements   ListFormat = LFMultiLine
	LFClassHeritageClauses              ListFormat = LFSingleLine
	LFClassMembers                      ListFormat = LFIndented | LFMultiLine
	LFInterfaceMembers                  ListFormat = LFIndented | LFMultiLine
	LFEnumMembers                       ListFormat = LFCommaDelimited | LFIndented | LFMultiLine
	LFCaseBlockClauses                  ListFormat = LFIndented | LFMultiLine
	LFNamedImportsOrExportsElements     ListFormat = LFCommaDelimited | LFSpaceBetweenSiblings | LFAllowTrailingComma | LFSingleLine | LFSpaceBetweenBraces | LFNoSpaceIfEmpty
	LFJsxElementOrFragmentChildren      ListFormat = LFSingleLine | LFNoInterveningComments
	LFJsxElementAttributes              ListFormat = LFSingleLine | LFSpaceBetweenSiblings | LFNoInterveningComments
	LFCaseOrDefaultClauseStatements     ListFormat = LFIndented | LFMultiLine | LFNoTrailingNewLine | LFOptionalIfEmpty
	LFHeritageClauseTypes               ListFormat = LFCommaDelimited | LFSpaceBetweenSiblings | LFSingleLine
	LFSourceFileStatements              ListFormat = LFMultiLine | LFNoTrailingNewLine
	LFDecorators                        ListFormat = LFMultiLine | LFOptional | LFSpaceAfterList
	LFTypeArguments                     ListFormat = LFCommaDelimited | LFSpaceBetweenSiblings | LFSingleLine | LFAngleBrackets | LFOptional
	LFTypeParameters                    ListFormat = LFCommaDelimited | LFSpaceBetweenSiblings | LFSingleLine | LFAngleBrackets | LFOptional
	LFParameters                        ListFormat = LFCommaDelimited | LFSpaceBetweenSiblings | LFSingleLine | LFParenthesis
	LFSingleArrowParameter              ListFormat = LFCommaDelimited | LFSpaceBetweenSiblings | LFSingleLine
	LFIndexSignatureParameters          ListFormat = LFCommaDelimited | LFSpaceBetweenSiblings | LFSingleLine | LFIndented | LFSquareBrackets
	LFJSDocComment                      ListFormat = LFMultiLine | LFAsteriskDelimited
	LFImportClauseEntries               ListFormat = LFImportAttributes // Deprecated: Use LFImportAttributes
)

func getOpeningBracket(format ListFormat) string {
	switch format & LFBracketsMask {
	case LFBraces:
		return "{"
	case LFParenthesis:
		return "("
	case LFAngleBrackets:
		return "<"
	case LFSquareBrackets:
		return "["
	default:
		panic(fmt.Sprintf("Unexpected bracket: %v", format&LFBracketsMask))
	}
}

func getClosingBracket(format ListFormat) string {
	switch format & LFBracketsMask {
	case LFBraces:
		return "}"
	case LFParenthesis:
		return ")"
	case LFAngleBrackets:
		return ">"
	case LFSquareBrackets:
		return "]"
	default:
		panic(fmt.Sprintf("Unexpected bracket: %v", format&LFBracketsMask))
	}
}
